___CSS_LOADER_EXPORT___.push([module.id, "/* ============ Settings Menu (replaces old floating theme toggle) ============ */\r\n.settings-menu {\r\n    position: fixed;\r\n    top: 20px;\r\n    right: 20px;\r\n    z-index: 1000;\r\n}\r\n\r\n.settings-menu__btn {\r\n    width: 48px;\r\n    height: 48px;\r\n    border-radius: 50%;\r\n    display: inline-flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    cursor: pointer;\r\n    border: 1px solid var(--border-strong);\r\n    background: var(--surface);\r\n    color: var(--accent);\r\n    box-shadow: var(--shadow-sm);\r\n    transition:\r\n        transform 0.25s var(--ease-spring),\r\n        box-shadow 0.25s var(--ease-smooth),\r\n        border-color 0.2s;\r\n}\r\n\r\n.settings-menu__btn:hover {\r\n    transform: rotate(-8deg) scale(1.05);\r\n    border-color: var(--accent);\r\n    box-shadow:\r\n        0 0 0 6px var(--accent-soft),\r\n        var(--shadow-md);\r\n}\r\n\r\n.settings-menu__btn.is-open {\r\n    transform: rotate(90deg);\r\n    border-color: var(--accent);\r\n    box-shadow:\r\n        0 0 0 6px var(--accent-soft),\r\n        var(--shadow-md);\r\n}\r\n\r\n.settings-menu__btn .anticon {\r\n    font-size: 20px;\r\n}\r\n\r\n[data-theme=\"black\"] .settings-menu__btn {\r\n    color: #60a5fa;\r\n}\r\n\r\n/* Dropdown panel */\r\n.settings-menu__dropdown {\r\n    position: absolute;\r\n    top: 58px;\r\n    right: 0;\r\n    min-width: 190px;\r\n    padding: 8px;\r\n    border-radius: 14px;\r\n    border: 1px solid var(--border-strong);\r\n    background: var(--surface);\r\n    box-shadow: var(--shadow-md);\r\n    display: flex;\r\n    flex-direction: column;\r\n    gap: 4px;\r\n\r\n    transform-origin: top right;\r\n    opacity: 0;\r\n    visibility: hidden;\r\n    transform: scale(0.9) translateY(-8px);\r\n    pointer-events: none;\r\n    transition:\r\n        opacity 0.2s var(--ease-smooth),\r\n        transform 0.25s var(--ease-spring),\r\n        visibility 0.25s;\r\n}\r\n\r\n.settings-menu__dropdown.is-open {\r\n    opacity: 1;\r\n    visibility: visible;\r\n    transform: scale(1) translateY(0);\r\n    pointer-events: auto;\r\n}\r\n\r\n.settings-menu__item {\r\n    display: flex;\r\n    align-items: center;\r\n    gap: 10px;\r\n    padding: 10px 12px;\r\n    border-radius: 10px;\r\n    border: none;\r\n    background: transparent;\r\n    color: #1f2937;\r\n    font-size: 14px;\r\n    font-weight: 500;\r\n    cursor: pointer;\r\n    text-align: left;\r\n    transition:\r\n        background 0.15s ease,\r\n        color 0.15s ease;\r\n}\r\n\r\n.settings-menu__item:hover,\r\n.settings-menu__item:focus-visible {\r\n    background: var(--accent-soft);\r\n    color: var(--accent);\r\n    outline: none;\r\n}\r\n\r\n.settings-menu__icon {\r\n    display: inline-flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    font-size: 16px;\r\n    width: 18px;\r\n}\r\n\r\n[data-theme=\"black\"] .settings-menu__item {\r\n    color: #e5e7eb;\r\n}\r\n\r\n[data-theme=\"black\"] .settings-menu__item:hover,\r\n[data-theme=\"black\"] .settings-menu__item:focus-visible {\r\n    color: #60a5fa;\r\n}\r\n\r\n@media (max-width: 720px) {\r\n    .settings-menu {\r\n        top: 14px;\r\n        right: 14px;\r\n    }\r\n\r\n    .settings-menu__dropdown {\r\n        min-width: 170px;\r\n    }\r\n}\r\n\r\n@media (prefers-reduced-motion: reduce) {\r\n    .settings-menu__btn,\r\n    .settings-menu__dropdown {\r\n        transition: opacity 0.01s linear !important;\r\n        transform: none !important;\r\n    }\r\n}", ""]);
