___CSS_LOADER_EXPORT___.push([module.id, "/* ==============================================\r\n   AlumniDetails.css — Modern header card + dark theme\r\n   Aligned with FaqPage design tokens (cyan/teal glass)\r\n   ============================================== */\r\n\r\n/* ============ Design tokens scoped to drawer ============ */\r\n.preview-drawer {\r\n --ease-spring: cubic-bezier(0.22, 1, 0.36, 1);\r\n  --ease-smooth: cubic-bezier(0.4, 0, 0.2, 1);\r\n\r\n  --accent:        #4f46e5;\r\n  --accent-2:      #0ea5e9;\r\n  --accent-3:      #7c3aed;\r\n  --accent-soft:   rgba(79, 70, 229, 0.10);\r\n  --accent-ring:   rgba(79, 70, 229, 0.26);\r\n\r\n  --bg:            #f4f7fb;\r\n  --surface:       #ffffff;\r\n  --surface-2:     #f1f5f9;\r\n  --border:        #e2e8f0;\r\n  --border-strong: #cbd5e1;\r\n\r\n  --text:         #0b1220;\r\n  --text-muted:   #5b6677;\r\n  --text-subtle:  #94a3b8;\r\n\r\n  --shadow-xs: 0 1px 2px  rgba(2, 6, 23, 0.05);\r\n  --shadow-sm: 0 4px 14px rgba(2, 6, 23, 0.06);\r\n  --shadow-md: 0 14px 34px rgba(2, 6, 23, 0.10);\r\n  --shadow-lg: 0 28px 60px rgba(2, 6, 23, 0.18);\r\n\r\n  --radius-sm: 10px;\r\n  --radius-md: 14px;\r\n  --radius-lg: 18px;\r\n  --radius-xl: 26px;\r\n/* \r\n  min-height: 100vh;\r\n  width: 100%;\r\n  padding: 32px 20px 64px;\r\n  display: flex;\r\n  justify-content: center;\r\n  align-items: flex-start;\r\n  position: relative;\r\n  z-index: 10; */\r\n\r\n  color: var(--text);\r\n  font-family: -apple-system, BlinkMacSystemFont, \"Inter\", \"Segoe UI\", Roboto,\r\n               \"Helvetica Neue\", Arial, sans-serif;\r\n\r\n  background:\r\n    radial-gradient(900px 500px at 100% -10%, rgba(14, 165, 233, 0.10), transparent 60%),\r\n    radial-gradient(900px 500px at -10% 110%, rgba(124, 58, 237, 0.10), transparent 60%),\r\n    var(--bg);\r\n  transition: background 0.3s ease, color 0.3s ease;\r\n}\r\n\r\n/* ============ Drawer header (title + Close/Submit buttons) ============\r\n   antd's default Drawer header keeps title and extra actions on one row\r\n   with no wrapping and a fixed height. When the title text is long\r\n   (company name appended) and the viewport is narrow, the title wraps\r\n   onto multiple lines but the header height doesn't grow to match, so\r\n   the Close/Submit buttons end up floating on top of the wrapped text.\r\n   Force the header to size to its content and stack on small screens. */\r\n.preview-drawer .ant-drawer-header {\r\n    height: auto !important;\r\n    flex-wrap: wrap !important;\r\n    row-gap: 10px;\r\n}\r\n.preview-drawer .ant-drawer-header-title {\r\n    min-width: 0;\r\n    flex: 1 1 260px;\r\n}\r\n.preview-drawer .ant-drawer-title {\r\n    white-space: normal !important;\r\n    overflow: visible !important;\r\n    text-overflow: unset !important;\r\n    line-height: 1.35 !important;\r\n}\r\n.preview-drawer .ant-drawer-extra {\r\n    flex: 0 0 auto;\r\n}\r\n\r\n@media (max-width: 576px) {\r\n    .preview-drawer .ant-drawer-header {\r\n        flex-direction: column;\r\n        align-items: flex-start !important;\r\n        padding: 12px 16px !important;\r\n    }\r\n    .preview-drawer .ant-drawer-header-title {\r\n        width: 100%;\r\n        flex-basis: auto;\r\n    }\r\n    .preview-drawer .ant-drawer-title {\r\n        font-size: 15px !important;\r\n    }\r\n    .preview-drawer .ant-drawer-extra {\r\n        width: 100%;\r\n    }\r\n    .preview-drawer .ant-drawer-extra .ant-space {\r\n        width: 100%;\r\n    }\r\n    .preview-drawer .ant-drawer-extra .ant-space-item {\r\n        flex: 1;\r\n    }\r\n    .preview-drawer .ant-drawer-extra .ant-btn {\r\n        width: 100%;\r\n    }\r\n}\r\n\r\n/* ============ Header card extras (works with inline styles) ============ */\r\n.preview-drawer .preview-header.preview-header--modern {\r\n    border-top-left-radius: 0;\r\n    border-top-right-radius: 0;\r\n    isolation: isolate;\r\n}\r\n\r\n.preview-drawer .preview-header__shape {\r\n    z-index: 0;\r\n}\r\n\r\n.preview-drawer .preview-profile-section {\r\n    z-index: 1;\r\n}\r\n\r\n/* Make the header readable on every theme */\r\n.preview-drawer .preview-header .ant-typography {\r\n    color: #ffffff !important;\r\n}\r\n\r\n/* Smooth focus rings on chips */\r\n.preview-drawer .contact-item.contact-item--chip:focus-within {\r\n    outline: 2px solid rgba(255, 255, 255, 0.4);\r\n    outline-offset: 2px;\r\n}\r\n\r\n\r\n\r\n/* ============ BLACK THEME (data-theme=\"black\") ============ */\r\n[data-theme=\"black\"] .preview-drawer .ant-drawer-body {\r\n    background: #0a0a0a !important;\r\n}\r\n\r\n[data-theme=\"black\"] .preview-drawer .ant-drawer-header {\r\n    background: #111418 !important;\r\n    border-bottom: 1px solid #242a36 !important;\r\n}\r\n\r\n[data-theme=\"black\"] .preview-drawer .ant-drawer-title,\r\n[data-theme=\"black\"] .preview-drawer .ant-drawer-close {\r\n    color: #ffffff !important;\r\n}\r\n\r\n[data-theme=\"black\"] .preview-drawer .drawer-content {\r\n    background: #0a0a0a !important;\r\n}\r\n\r\n/* Header card: deeper background, keep accents */\r\n[data-theme=\"black\"] .preview-drawer .preview-header.preview-header--modern {\r\n    background:\r\n        radial-gradient(820px 360px at 112% -12%, rgba(37, 99, 235, 0.40), transparent 60%),\r\n        radial-gradient(680px 360px at -10% 120%, rgba(193, 18, 31, 0.30), transparent 60%),\r\n        linear-gradient(135deg, #050b1c 0%, #0b1f4d 40%, #14306e 100%) !important;\r\n    border-bottom: 2px solid rgba(193, 18, 31, 0.55) !important;\r\n}\r\n\r\n[data-theme=\"black\"] .preview-drawer .preview-header * {\r\n    color: #ffffff !important;\r\n}\r\n\r\n[data-theme=\"black\"] .preview-drawer .preview-name {\r\n    color: #ffffff !important;\r\n}\r\n\r\n[data-theme=\"black\"] .preview-drawer .preview-title,\r\n[data-theme=\"black\"] .preview-drawer .contact-label {\r\n    color: rgba(255, 255, 255, 0.78) !important;\r\n}\r\n\r\n[data-theme=\"black\"] .preview-drawer .contact-item.contact-item--chip {\r\n    background: rgba(11, 31, 77, 0.55) !important;\r\n    border-color: rgba(193, 18, 31, 0.45) !important;\r\n}\r\n\r\n/* Keep OCC toga/emblem accents in black theme */\r\n[data-theme=\"black\"] .preview-drawer .profile-status-dot {\r\n    border-color: #0b1f4d !important;\r\n}\r\n\r\n[data-theme=\"black\"] .preview-drawer .profile-status-dot {\r\n    border-color: #05070d !important;\r\n}\r\n\r\n/* ============ Cards (body sections) — preserve original behavior ============ */\r\n[data-theme=\"black\"] .preview-drawer .preview-card,\r\n[data-theme=\"black\"] .preview-drawer .ant-card,\r\n[data-theme=\"black\"] .preview-drawer .sidebar-card {\r\n    background: #121620 !important;\r\n    border-color: #242a36 !important;\r\n}\r\n\r\n[data-theme=\"black\"] .preview-drawer .ant-card-body {\r\n    background: #121620 !important;\r\n}\r\n\r\n[data-theme=\"black\"] .preview-drawer .ant-typography,\r\n[data-theme=\"black\"] .preview-drawer .section-title,\r\n[data-theme=\"black\"] .preview-drawer .sidebar-title,\r\n[data-theme=\"black\"] .preview-drawer .subsection-title,\r\n[data-theme=\"black\"] .preview-drawer .detail-item span,\r\n[data-theme=\"black\"] .preview-drawer .preview-text,\r\n[data-theme=\"black\"] .preview-drawer .preview-bio,\r\n[data-theme=\"black\"] .preview-drawer .sidebar-label,\r\n[data-theme=\"black\"] .preview-drawer .sidebar-value,\r\n[data-theme=\"black\"] .preview-drawer .preference-item span,\r\n[data-theme=\"black\"] .preview-drawer .document-item span,\r\n[data-theme=\"black\"] .preview-drawer .honor-item span {\r\n    color: #ffffff !important;\r\n}\r\n\r\n[data-theme=\"black\"] .preview-drawer h1,\r\n[data-theme=\"black\"] .preview-drawer h2,\r\n[data-theme=\"black\"] .preview-drawer h3,\r\n[data-theme=\"black\"] .preview-drawer h4,\r\n[data-theme=\"black\"] .preview-drawer h5,\r\n[data-theme=\"black\"] .preview-drawer h6,\r\n[data-theme=\"black\"] .preview-drawer .ant-typography-secondary {\r\n    color: #ffffff !important;\r\n}\r\n\r\n[data-theme=\"black\"] .preview-body {\r\n    background: #0a0a0a !important;\r\n}\r\n\r\n[data-theme=\"black\"] .preview-drawer .subsection {\r\n    border-color: #242a36 !important;\r\n}\r\n\r\n[data-theme=\"black\"] .preview-drawer .subsection .preview-text {\r\n    background: #1a1f2b !important;\r\n    color: #ffffff !important;\r\n    border-color: #242a36 !important;\r\n}\r\n\r\n[data-theme=\"black\"] .preview-drawer .sidebar-item:hover {\r\n    background: #1a1f2b !important;\r\n}\r\n\r\n[data-theme=\"black\"] .preview-drawer .sidebar-icon {\r\n    color: #aaaaaa !important;\r\n}\r\n\r\n[data-theme=\"black\"] .preview-drawer .sidebar-icon.linkedin {\r\n    color: #0a66c2 !important;\r\n}\r\n\r\n[data-theme=\"black\"] .preview-drawer .sidebar-icon.github {\r\n    color: #ffffff !important;\r\n}\r\n\r\n[data-theme=\"black\"] .preview-drawer .honor-item {\r\n    background: #1a1f2b !important;\r\n    border-color: #242a36 !important;\r\n}\r\n\r\n[data-theme=\"black\"] .preview-drawer .document-item.pending span {\r\n    color: #8c8c8c !important;\r\n}\r\n\r\n[data-theme=\"black\"] .preview-drawer .document-item.uploaded span {\r\n    color: #52c41a !important;\r\n}\r\n\r\n[data-theme=\"black\"] .image-zoom-modal .ant-modal-content,\r\n[data-theme=\"black\"] .image-zoom-modal .ant-modal-header {\r\n    background: #121620 !important;\r\n}\r\n\r\n[data-theme=\"black\"] .image-zoom-modal .ant-modal-header {\r\n    border-bottom: 1px solid #242a36 !important;\r\n}\r\n\r\n[data-theme=\"black\"] .image-zoom-modal .ant-modal-title,\r\n[data-theme=\"black\"] .image-zoom-modal .ant-modal-close {\r\n    color: #ffffff !important;\r\n}\r\n\r\n[data-theme=\"black\"] .image-zoom-modal .zoom-container {\r\n    background: #121620 !important;\r\n}\r\n\r\n[data-theme=\"black\"] .preview-drawer .ant-divider {\r\n    border-color: #242a36 !important;\r\n}\r\n\r\n[data-theme=\"black\"] .preview-drawer .ant-btn-default {\r\n    background: #1a1f2b !important;\r\n    border-color: #303746 !important;\r\n    color: #ffffff !important;\r\n}\r\n\r\n[data-theme=\"black\"] .preview-drawer .ant-btn-default:hover {\r\n    background: #242a36 !important;\r\n    border-color: #3a4252 !important;\r\n    color: #ffffff !important;\r\n}\r\n\r\n[data-theme=\"black\"] .preview-drawer .ant-row {\r\n    background: transparent !important;\r\n}\r\n\r\n[data-theme=\"black\"] .preview-drawer .career-details,\r\n[data-theme=\"black\"] .preview-drawer .academic-details {\r\n    background: transparent !important;\r\n}\r\n\r\n[data-theme=\"black\"] .preview-drawer .preview-card[style*=\"border-color: red\"] {\r\n    background: #121620 !important;\r\n}", ""]);
