___CSS_LOADER_EXPORT___.push([module.id, "/* ==========================================================================\r\n   PublicPages404.css\r\n   OCC Alumni — Public \"Page Not Found\" screen\r\n   Imports PublicHomePage.css for shared tokens (--ph-accent, .ph-btn,\r\n   .grad, .ph-theme-btn); everything here is additive, namespaced with a\r\n   \"pp404-\" prefix so nothing collides with the rest of the public site.\r\n   ========================================================================== */\r\n\r\n.pp404-page {\r\n  position: relative;\r\n  min-height: 100vh;\r\n  min-height: 100dvh;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  padding: 24px;\r\n  padding-top: calc(24px + env(safe-area-inset-top));\r\n  padding-bottom: calc(24px + env(safe-area-inset-bottom));\r\n  padding-left: calc(24px + env(safe-area-inset-left));\r\n  padding-right: calc(24px + env(safe-area-inset-right));\r\n  overflow: hidden;\r\n  box-sizing: border-box;\r\n}\r\n\r\n.pp404-bg {\r\n  position: absolute;\r\n  inset: 0;\r\n  z-index: 0;\r\n  background: linear-gradient(\r\n    135deg,\r\n    rgba(79, 70, 229, 0.08),\r\n    rgba(14, 165, 233, 0.08) 55%,\r\n    rgba(124, 58, 237, 0.08)\r\n  );\r\n}\r\n\r\n.ph-page.dark .pp404-bg {\r\n  background: linear-gradient(\r\n    135deg,\r\n    rgba(79, 70, 229, 0.14),\r\n    rgba(14, 165, 233, 0.1) 55%,\r\n    rgba(124, 58, 237, 0.14)\r\n  );\r\n}\r\n\r\n.pp404-theme-btn {\r\n  position: absolute;\r\n  top: calc(20px + env(safe-area-inset-top));\r\n  right: calc(20px + env(safe-area-inset-right));\r\n  z-index: 2;\r\n}\r\n\r\n.pp404-card {\r\n  position: relative;\r\n  z-index: 1;\r\n  width: min(100%, 560px);\r\n  max-width: 560px;\r\n  box-sizing: border-box;\r\n  text-align: center;\r\n  padding: 48px 40px 40px;\r\n  border-radius: 24px;\r\n}\r\n\r\n.ph-page.light .pp404-card {\r\n  background: #ffffff;\r\n  border: 1px solid #e6eaf1;\r\n  box-shadow: 0 24px 60px rgba(2, 6, 23, 0.08);\r\n}\r\n\r\n.ph-page.dark .pp404-card {\r\n  background: rgba(18, 22, 32, 0.85);\r\n  border: 1px solid #242a36;\r\n  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.35);\r\n}\r\n\r\n.pp404-brand {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 10px;\r\n  cursor: pointer;\r\n  margin-bottom: 28px;\r\n}\r\n\r\n.pp404-brand img {\r\n  height: 40px;\r\n  width: auto;\r\n}\r\n\r\n.pp404-brand-title {\r\n  font-size: 17px;\r\n  font-weight: 800;\r\n}\r\n\r\n.pp404-code {\r\n  font-size: 84px;\r\n  font-weight: 900;\r\n  line-height: 1;\r\n  letter-spacing: -0.02em;\r\n  margin-bottom: 8px;\r\n  color: inherit;\r\n}\r\n\r\n.pp404-title {\r\n  margin: 0 0 12px !important;\r\n  color: inherit !important;\r\n  font-size: 24px !important;\r\n  font-weight: 800 !important;\r\n}\r\n\r\n.pp404-sub {\r\n  opacity: 0.72;\r\n  color: inherit !important;\r\n  font-size: 14.5px !important;\r\n  margin: 0 auto 20px !important;\r\n  max-width: 440px;\r\n}\r\n\r\n.pp404-path {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n  flex-wrap: wrap;\r\n  justify-content: center;\r\n  font-size: 13px;\r\n  padding: 8px 14px;\r\n  border-radius: 999px;\r\n  margin: 0 auto 26px;\r\n  max-width: 100%;\r\n}\r\n\r\n.ph-page.light .pp404-path {\r\n  background: #f5f7fb;\r\n  border: 1px solid #e6eaf1;\r\n  color: #475569;\r\n}\r\n\r\n.ph-page.dark .pp404-path {\r\n  background: rgba(255, 255, 255, 0.05);\r\n  border: 1px solid #242a36;\r\n  color: #cbd5e1;\r\n}\r\n\r\n.pp404-path code {\r\n  background: transparent;\r\n  color: var(--ph-accent);\r\n  font-weight: 700;\r\n  word-break: break-all;\r\n}\r\n\r\n.pp404-actions {\r\n  display: flex;\r\n  justify-content: center;\r\n  margin-bottom: 16px;\r\n}\r\n\r\n.pp404-countdown {\r\n  display: block;\r\n  font-size: 12.5px !important;\r\n  opacity: 0.6;\r\n  color: inherit !important;\r\n}\r\n\r\n/* ==========================================================================\r\n   RESPONSIVE — tablets down to the smallest phones, portrait & landscape\r\n   ========================================================================== */\r\n\r\n/* Small tablets / large phones (e.g. iPad Mini portrait, phablets) */\r\n@media (max-width: 768px) {\r\n  .pp404-page { padding: 20px; }\r\n  .pp404-card { padding: 44px 32px 36px; border-radius: 20px; }\r\n  .pp404-code { font-size: 72px; }\r\n}\r\n\r\n/* Standard phones — portrait (iPhone 12/13/14/15, Pixel, Galaxy S-series) */\r\n@media (max-width: 575px) {\r\n  .pp404-card { padding: 40px 24px 32px; border-radius: 18px; }\r\n  .pp404-code { font-size: 64px; }\r\n  .pp404-title { font-size: 20px !important; }\r\n  .pp404-sub { font-size: 13.5px !important; }\r\n  .pp404-brand img { height: 34px; }\r\n  .pp404-path { font-size: 12px; padding: 7px 12px; }\r\n  .pp404-actions .ph-btn { width: 100%; justify-content: center; }\r\n}\r\n\r\n/* Compact phones (e.g. iPhone SE, older/smaller Androids) */\r\n@media (max-width: 400px) {\r\n  .pp404-page { padding: 16px; }\r\n  .pp404-card { padding: 36px 20px 28px; }\r\n  .pp404-code { font-size: 58px; }\r\n  .pp404-brand { margin-bottom: 22px; }\r\n  .pp404-brand-title { font-size: 15px; }\r\n}\r\n\r\n/* Smallest phones (e.g. iPhone 5/SE 1st gen, Galaxy Fold outer screen) */\r\n@media (max-width: 374px) {\r\n  .pp404-card { padding: 32px 16px 26px; border-radius: 16px; }\r\n  .pp404-code { font-size: 50px; }\r\n  .pp404-title { font-size: 18px !important; }\r\n  .pp404-sub { font-size: 13px !important; margin-bottom: 16px !important; }\r\n  .pp404-path { font-size: 11px; gap: 6px; }\r\n}\r\n\r\n@media (max-width: 320px) {\r\n  .pp404-card { padding: 28px 14px 22px; }\r\n  .pp404-code { font-size: 44px; }\r\n  .pp404-brand img { height: 30px; }\r\n}\r\n\r\n/* Phones — landscape (short viewport height, wide width) */\r\n@media (max-width: 900px) and (orientation: landscape) {\r\n  .pp404-page { padding: 16px; overflow-y: auto; }\r\n  .pp404-card { padding: 28px 32px; }\r\n  .pp404-brand { margin-bottom: 16px; }\r\n  .pp404-code { font-size: 56px; margin-bottom: 4px; }\r\n  .pp404-sub { margin-bottom: 14px !important; }\r\n  .pp404-path { margin-bottom: 16px; }\r\n}\r\n\r\n/* Very short landscape (e.g. small phones rotated) — trims the least\r\n   essential copy so the card + primary action still fit above the fold */\r\n@media (max-height: 400px) and (orientation: landscape) {\r\n  .pp404-page { align-items: flex-start; }\r\n  .pp404-brand { margin-bottom: 10px; }\r\n  .pp404-code { font-size: 42px; margin-bottom: 2px; }\r\n  .pp404-title { font-size: 17px !important; margin-bottom: 6px !important; }\r\n  .pp404-sub { display: none; }\r\n  .pp404-path { margin-bottom: 12px; }\r\n  .pp404-actions { margin-bottom: 8px; }\r\n}\r\n\r\n/* Foldables / narrow-but-tall screens (e.g. Galaxy Fold outer, Z Flip) */\r\n@media (max-width: 320px) and (min-height: 650px) {\r\n  .pp404-card { padding: 30px 14px 24px; }\r\n}", ""]);
