___CSS_LOADER_EXPORT___.push([module.id, "/* ============ Design Tokens ============ */\r\n.about-page {\r\n  --ease-spring: cubic-bezier(0.22, 1, 0.36, 1);\r\n  --ease-smooth: cubic-bezier(0.4, 0, 0.2, 1);\r\n  --accent: #4f46e5;\r\n  --accent-2: #7c3aed;\r\n  --accent-3: #0ea5e9;\r\n  --accent-soft: rgba(79, 70, 229, 0.08);\r\n  --accent-ring: rgba(79, 70, 229, 0.22);\r\n  --bg: #f6f7fb;\r\n  --surface: #ffffff;\r\n  --surface-2: #f3f4f6;\r\n  --border: #e5e7eb;\r\n  --border-strong: #d1d5db;\r\n  --text: #0f172a;\r\n  --text-muted: #64748b;\r\n  --text-subtle: #94a3b8;\r\n  --shadow-xs: 0 1px 2px rgba(15, 23, 42, 0.04);\r\n  --shadow-sm: 0 2px 10px rgba(15, 23, 42, 0.06);\r\n  --shadow-md: 0 10px 28px rgba(15, 23, 42, 0.08);\r\n  --shadow-lg: 0 22px 48px rgba(15, 23, 42, 0.14);\r\n  --radius-sm: 10px;\r\n  --radius-md: 14px;\r\n  --radius-lg: 18px;\r\n  --radius-xl: 24px;\r\n\r\n\r\n     padding: 24px;\r\n  padding-top: 10px;\r\n  min-height: 100vh;\r\n  position: relative;\r\n  z-index: 1;\r\n\r\n\r\n\r\n  color: var(--text);\r\n  font-family: -apple-system, BlinkMacSystemFont, \"Inter\", \"Segoe UI\",\r\n    Roboto, \"Helvetica Neue\", Arial, sans-serif;\r\n  opacity: 0;\r\n  transform: translateY(8px);\r\n  transition: opacity 0.6s var(--ease-smooth),\r\n    transform 0.6s var(--ease-smooth);\r\n}\r\n\r\n.about-page.is-revealed {\r\n  opacity: 1;\r\n  transform: translateY(0);\r\n}\r\n\r\n/* ============ Back to Login ============ */\r\n.back-to-login-section { margin-bottom: 8px; text-align: left; }\r\n.back-to-login-btn {\r\n  color: var(--text-muted) !important;\r\n  font-weight: 600 !important;\r\n  padding: 4px 10px !important;\r\n  border-radius: 10px !important;\r\n  transition: all 0.25s var(--ease-smooth);\r\n}\r\n.back-to-login-btn:hover,\r\n.back-to-login-btn:focus {\r\n  color: var(--accent) !important;\r\n  background: var(--accent-soft) !important;\r\n}\r\n\r\n/* Dark theme support */\r\n[data-theme=\"black\"] .about-page {\r\n  --bg: #0b0c10;\r\n  --surface: #14161d;\r\n  --surface-2: #1b1e27;\r\n  --border: #262a33;\r\n  --border-strong: #2f3440;\r\n  --text: #e7e9ee;\r\n  --text-muted: #9ba3af;\r\n  --text-subtle: #6b7280;\r\n  --shadow-xs: 0 1px 2px rgba(0, 0, 0, 0.4);\r\n  --shadow-sm: 0 2px 10px rgba(0, 0, 0, 0.35);\r\n  --shadow-md: 0 10px 28px rgba(0, 0, 0, 0.45);\r\n  --shadow-lg: 0 22px 48px rgba(0, 0, 0, 0.55);\r\n  --accent-soft: rgba(99, 102, 241, 0.14);\r\n}\r\n\r\n/* ============ Keyframes ============ */\r\n@keyframes fadeUp {\r\n  from {\r\n    opacity: 0;\r\n    transform: translateY(14px);\r\n  }\r\n\r\n  to {\r\n    opacity: 1;\r\n    transform: translateY(0);\r\n  }\r\n}\r\n\r\n@keyframes fadeIn {\r\n  from {\r\n    opacity: 0;\r\n  }\r\n\r\n  to {\r\n    opacity: 1;\r\n  }\r\n}\r\n\r\n@keyframes floatY {\r\n\r\n  0%,\r\n  100% {\r\n    transform: translateY(0);\r\n  }\r\n\r\n  50% {\r\n    transform: translateY(-12px);\r\n  }\r\n}\r\n\r\n@keyframes orbit {\r\n  0% {\r\n    transform: translate(0, 0) scale(1);\r\n  }\r\n\r\n  50% {\r\n    transform: translate(20px, -20px) scale(1.08);\r\n  }\r\n\r\n  100% {\r\n    transform: translate(0, 0) scale(1);\r\n  }\r\n}\r\n\r\n@keyframes shine {\r\n  0% {\r\n    transform: translateX(-150%) skewX(-18deg);\r\n  }\r\n\r\n  100% {\r\n    transform: translateX(250%) skewX(-18deg);\r\n  }\r\n}\r\n\r\n/* ============ HERO ============ */\r\n.about-hero {\r\n  position: relative;\r\n  overflow: hidden;\r\n  /* wrapper handles centering */\r\n  padding: 64px 28px 44px;\r\n  border-radius: var(--radius-xl);\r\n  background:\r\n    radial-gradient(1200px 500px at -10% -20%, rgba(79, 70, 229, 0.18), transparent 60%),\r\n    radial-gradient(900px 400px at 110% 0%, rgba(14, 165, 233, 0.18), transparent 60%),\r\n    linear-gradient(180deg, var(--surface) 0%, var(--surface) 100%);\r\n  border: 1px solid var(--border);\r\n  box-shadow: var(--shadow-md);\r\n}\r\n\r\n.about-hero__bg {\r\n  position: absolute;\r\n  inset: 0;\r\n  pointer-events: none;\r\n  overflow: hidden;\r\n}\r\n\r\n.about-hero__bg .orb {\r\n  position: absolute;\r\n  border-radius: 50%;\r\n  filter: blur(60px);\r\n  opacity: 0.55;\r\n  animation: orbit 14s ease-in-out infinite;\r\n}\r\n\r\n.orb-1 {\r\n  width: 260px;\r\n  height: 260px;\r\n  background: #6366f1;\r\n  top: -60px;\r\n  left: -40px;\r\n}\r\n\r\n.orb-2 {\r\n  width: 320px;\r\n  height: 320px;\r\n  background: #06b6d4;\r\n  bottom: -120px;\r\n  right: -60px;\r\n  animation-duration: 18s;\r\n}\r\n\r\n.orb-3 {\r\n  width: 200px;\r\n  height: 200px;\r\n  background: #a855f7;\r\n  top: 40%;\r\n  left: 50%;\r\n  animation-duration: 22s;\r\n  opacity: 0.35;\r\n}\r\n\r\n.grid-overlay {\r\n  position: absolute;\r\n  inset: 0;\r\n  background-image:\r\n    linear-gradient(to right, rgba(15, 23, 42, 0.06) 1px, transparent 1px),\r\n    linear-gradient(to bottom, rgba(15, 23, 42, 0.06) 1px, transparent 1px);\r\n  background-size: 36px 36px;\r\n  mask-image: radial-gradient(ellipse at center, black 30%, transparent 75%);\r\n  -webkit-mask-image: radial-gradient(ellipse at center, black 30%, transparent 75%);\r\n}\r\n\r\n[data-theme=\"black\"] .grid-overlay {\r\n  background-image:\r\n    linear-gradient(to right, rgba(255, 255, 255, 0.05) 1px, transparent 1px),\r\n    linear-gradient(to bottom, rgba(255, 255, 255, 0.05) 1px, transparent 1px);\r\n}\r\n\r\n.about-hero__content {\r\n  position: relative;\r\n  z-index: 1;\r\n  max-width: 920px;\r\n  margin: 0 auto;\r\n  text-align: center;\r\n  animation: fadeUp 0.7s var(--ease-spring) both;\r\n}\r\n\r\n.about-hero__brand {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 14px;\r\n  margin-bottom: 18px;\r\n}\r\n\r\n.about-hero__logo {\r\n  height: 56px;\r\n  width: 56px;\r\n  -o-object-fit: contain;\r\n     object-fit: contain;\r\n  border-radius: 12px;\r\n  background: var(--surface);\r\n  padding: 6px;\r\n  box-shadow: var(--shadow-sm);\r\n  animation: floatY 6s ease-in-out infinite;\r\n}\r\n\r\n.about-hero__brand-meta {\r\n  display: flex;\r\n  flex-direction: column;\r\n  align-items: flex-start;\r\n  gap: 4px;\r\n}\r\n\r\n.about-chip {\r\n  background: var(--accent-soft) !important;\r\n  color: var(--accent) !important;\r\n  border: 1px solid var(--accent-ring) !important;\r\n  border-radius: 999px !important;\r\n  padding: 4px 12px !important;\r\n  font-weight: 600 !important;\r\n  font-size: 12px !important;\r\n  margin: 0 !important;\r\n}\r\n\r\n.about-hero__eyebrow {\r\n  color: var(--text-muted);\r\n  font-size: 13px;\r\n  letter-spacing: 0.08em;\r\n  text-transform: uppercase;\r\n}\r\n\r\n.about-hero__title {\r\n  font-size: clamp(32px, 5vw, 56px) !important;\r\n  line-height: 1.08 !important;\r\n  font-weight: 800 !important;\r\n  margin: 8px 0 16px !important;\r\n  color: var(--text) !important;\r\n  letter-spacing: -0.02em;\r\n}\r\n\r\n.grad-text {\r\n  background: linear-gradient(135deg, var(--accent) 0%, var(--accent-3) 50%, var(--accent-2) 100%);\r\n  -webkit-background-clip: text;\r\n  background-clip: text;\r\n  -webkit-text-fill-color: transparent;\r\n  color: transparent;\r\n}\r\n\r\n.about-hero__lead {\r\n  color: var(--text-muted) !important;\r\n  font-size: 17px !important;\r\n  line-height: 1.7 !important;\r\n  max-width: 760px;\r\n  margin: 0 auto 28px !important;\r\n}\r\n\r\n.about-hero__cta {\r\n  justify-content: center;\r\n  display: flex;\r\n}\r\n\r\n.btn-primary-grad {\r\n  background: linear-gradient(135deg, var(--accent), var(--accent-2)) !important;\r\n  border: none !important;\r\n  height: 46px !important;\r\n  padding: 0 24px !important;\r\n  border-radius: 12px !important;\r\n  font-weight: 600 !important;\r\n  box-shadow: 0 10px 24px var(--accent-ring) !important;\r\n  position: relative;\r\n  overflow: hidden;\r\n}\r\n\r\n.btn-primary-grad::after {\r\n  content: \"\";\r\n  position: absolute;\r\n  top: 0;\r\n  left: 0;\r\n  width: 60%;\r\n  height: 100%;\r\n  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.35), transparent);\r\n  animation: shine 2.8s ease-in-out infinite;\r\n}\r\n\r\n.btn-primary-grad:hover {\r\n  transform: translateY(-1px);\r\n}\r\n\r\n.btn-ghost {\r\n  height: 46px !important;\r\n  padding: 0 22px !important;\r\n  border-radius: 12px !important;\r\n  font-weight: 600 !important;\r\n  background: var(--surface) !important;\r\n  border: 1px solid var(--border-strong) !important;\r\n  color: var(--text) !important;\r\n}\r\n\r\n.btn-ghost:hover {\r\n  border-color: var(--accent) !important;\r\n  color: var(--accent) !important;\r\n}\r\n\r\n/* Hero Stats */\r\n.about-hero__stats {\r\n  margin-top: 40px !important;\r\n}\r\n\r\n.stat-card {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 12px;\r\n  padding: 14px 16px;\r\n  border-radius: var(--radius-md);\r\n  background: var(--surface);\r\n  border: 1px solid var(--border);\r\n  box-shadow: var(--shadow-xs);\r\n  transition: transform 0.3s var(--ease-smooth), box-shadow 0.3s var(--ease-smooth);\r\n  text-align: left;\r\n}\r\n\r\n.stat-card:hover {\r\n  transform: translateY(-3px);\r\n  box-shadow: var(--shadow-md);\r\n  border-color: var(--accent-ring);\r\n}\r\n\r\n.stat-icon {\r\n  font-size: 22px;\r\n  color: var(--accent);\r\n  background: var(--accent-soft);\r\n  padding: 10px;\r\n  border-radius: 10px;\r\n}\r\n\r\n.stat-value {\r\n  display: block;\r\n  font-size: 18px;\r\n  font-weight: 700;\r\n  color: var(--text);\r\n  line-height: 1.1;\r\n}\r\n\r\n.stat-label {\r\n  display: block;\r\n  font-size: 12px;\r\n  color: var(--text-muted);\r\n  margin-top: 2px;\r\n}\r\n\r\n/* ============ Sections ============ */\r\n.about-section {\r\n  max-width: 1280px;\r\n  margin: 32px auto 0;\r\n  padding: 0 28px;\r\n  animation: fadeUp 0.7s var(--ease-spring) both;\r\n}\r\n\r\n.about-section--close {\r\n  margin-top: 48px;\r\n}\r\n\r\n.section-header {\r\n  text-align: center;\r\n  max-width: 760px;\r\n  margin: 0 auto 28px;\r\n}\r\n\r\n.section-chip {\r\n  background: var(--accent-soft) !important;\r\n  color: var(--accent) !important;\r\n  border: 1px solid var(--accent-ring) !important;\r\n  border-radius: 999px !important;\r\n  padding: 4px 12px !important;\r\n  font-weight: 600 !important;\r\n  font-size: 12px !important;\r\n  margin-bottom: 14px !important;\r\n  letter-spacing: 0.04em;\r\n}\r\n\r\n.section-chip--accent {\r\n  background: linear-gradient(135deg, rgba(124, 58, 237, 0.12), rgba(14, 165, 233, 0.12)) !important;\r\n  color: var(--accent-2) !important;\r\n  border-color: rgba(124, 58, 237, 0.25) !important;\r\n}\r\n\r\n.section-title {\r\n  color: var(--text) !important;\r\n  font-weight: 800 !important;\r\n  letter-spacing: -0.015em;\r\n  margin: 8px 0 12px !important;\r\n}\r\n\r\n.section-subtitle {\r\n  color: var(--text-muted) !important;\r\n  font-size: 15px !important;\r\n  line-height: 1.7 !important;\r\n  margin: 0 !important;\r\n}\r\n\r\n.section-paragraph {\r\n  color: var(--text-muted) !important;\r\n  font-size: 15px !important;\r\n  line-height: 1.8 !important;\r\n  margin-bottom: 14px !important;\r\n}\r\n\r\n/* ============ Cards ============ */\r\n.about-card {\r\n  background: var(--surface) !important;\r\n  border-radius: var(--radius-lg) !important;\r\n  border: 1px solid var(--border) !important;\r\n  box-shadow: var(--shadow-sm) !important;\r\n  height: 100%;\r\n  transition: box-shadow 0.3s var(--ease-smooth), transform 0.3s var(--ease-smooth);\r\n}\r\n\r\n.about-card .ant-card-body {\r\n  padding: 28px;\r\n}\r\n\r\n.about-card:hover {\r\n  box-shadow: var(--shadow-md) !important;\r\n}\r\n\r\n.about-card--overview .section-title {\r\n  font-size: 26px !important;\r\n}\r\n\r\n.about-card--goals {\r\n  background:\r\n    radial-gradient(600px 300px at 100% 0%, rgba(79, 70, 229, 0.08), transparent 60%),\r\n    var(--surface) !important;\r\n}\r\n\r\n.goals-list {\r\n  list-style: none;\r\n  margin: 18px 0 0;\r\n  padding: 0;\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 12px;\r\n}\r\n\r\n.goal-item {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 12px;\r\n  padding: 12px 14px;\r\n  background: var(--surface-2);\r\n  border: 1px solid var(--border);\r\n  border-radius: var(--radius-md);\r\n  transition: all 0.25s var(--ease-smooth);\r\n  animation: fadeUp 0.6s var(--ease-spring) both;\r\n}\r\n\r\n.goal-item:hover {\r\n  transform: translateX(4px);\r\n  background: var(--accent-soft);\r\n  border-color: var(--accent-ring);\r\n}\r\n\r\n.goal-icon {\r\n  width: 36px;\r\n  height: 36px;\r\n  display: inline-flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  border-radius: 10px;\r\n  background: linear-gradient(135deg, var(--accent), var(--accent-2));\r\n  color: #fff;\r\n  font-size: 16px;\r\n  flex-shrink: 0;\r\n}\r\n\r\n.goal-text {\r\n  color: var(--text) !important;\r\n  font-size: 14px;\r\n  font-weight: 500;\r\n}\r\n\r\n/* ============ Feature Cards ============ */\r\n.feature-card {\r\n  background: var(--surface) !important;\r\n  border-radius: var(--radius-lg) !important;\r\n  border: 1px solid var(--border) !important;\r\n  box-shadow: var(--shadow-xs) !important;\r\n  height: 100%;\r\n  transition: transform 0.35s var(--ease-spring), box-shadow 0.35s var(--ease-smooth), border-color 0.25s;\r\n  animation: fadeUp 0.6s var(--ease-spring) both;\r\n  position: relative;\r\n  overflow: hidden;\r\n}\r\n\r\n.feature-card:hover {\r\n  transform: translateY(-6px);\r\n  box-shadow: var(--shadow-md) !important;\r\n  border-color: var(--accent-ring) !important;\r\n}\r\n\r\n.feature-card .ant-card-body {\r\n  padding: 24px;\r\n}\r\n\r\n.feature-icon {\r\n  width: 52px;\r\n  height: 52px;\r\n  border-radius: 14px;\r\n  display: inline-flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  font-size: 24px;\r\n  margin-bottom: 16px;\r\n  transition: transform 0.3s var(--ease-spring);\r\n}\r\n\r\n.feature-card:hover .feature-icon {\r\n  transform: scale(1.08) rotate(-3deg);\r\n}\r\n\r\n.feature-title {\r\n  color: var(--text) !important;\r\n  font-size: 16px !important;\r\n  font-weight: 700 !important;\r\n  margin: 0 0 8px !important;\r\n  letter-spacing: -0.005em;\r\n}\r\n\r\n.feature-desc {\r\n  color: var(--text-muted) !important;\r\n  font-size: 13.5px !important;\r\n  line-height: 1.65 !important;\r\n  margin: 0 !important;\r\n}\r\n\r\n/* ============ Page Items ============ */\r\n.page-item {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 14px;\r\n  padding: 16px 18px;\r\n  background: var(--surface);\r\n  border: 1px solid var(--border);\r\n  border-radius: var(--radius-md);\r\n  box-shadow: var(--shadow-xs);\r\n  cursor: default;\r\n  transition: all 0.25s var(--ease-smooth);\r\n  animation: fadeUp 0.5s var(--ease-spring) both;\r\n  height: 100%;\r\n}\r\n\r\n.page-item:hover {\r\n  transform: translateY(-3px);\r\n  border-color: var(--accent);\r\n  box-shadow: var(--shadow-md);\r\n  background: linear-gradient(180deg, var(--surface), var(--accent-soft));\r\n}\r\n\r\n.page-item__index {\r\n  flex-shrink: 0;\r\n  width: 38px;\r\n  height: 38px;\r\n  display: inline-flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  border-radius: 10px;\r\n  background: linear-gradient(135deg, var(--accent), var(--accent-2));\r\n  color: #fff;\r\n  font-weight: 700;\r\n  font-size: 13px;\r\n  letter-spacing: 0.02em;\r\n  box-shadow: 0 6px 14px var(--accent-ring);\r\n}\r\n\r\n.page-item__body {\r\n  flex: 1;\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 2px;\r\n  min-width: 0;\r\n}\r\n\r\n.page-item__name {\r\n  color: var(--text) !important;\r\n  font-size: 14.5px;\r\n  font-weight: 700 !important;\r\n}\r\n\r\n.page-item__desc {\r\n  color: var(--text-muted) !important;\r\n  font-size: 12.5px;\r\n  line-height: 1.5;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  display: -webkit-box;\r\n  -webkit-line-clamp: 2;\r\n  -webkit-box-orient: vertical;\r\n}\r\n\r\n.page-item__arrow {\r\n  color: var(--text-subtle);\r\n  font-size: 14px;\r\n  transition: transform 0.25s var(--ease-smooth), color 0.25s;\r\n}\r\n\r\n.page-item:hover .page-item__arrow {\r\n  color: var(--accent);\r\n  transform: translateX(4px);\r\n}\r\n\r\n/* ============ Closing ============ */\r\n.about-closing {\r\n  background:\r\n    radial-gradient(900px 360px at 0% 0%, rgba(79, 70, 229, 0.10), transparent 60%),\r\n    radial-gradient(900px 360px at 100% 100%, rgba(14, 165, 233, 0.10), transparent 60%),\r\n    var(--surface) !important;\r\n  border: 1px solid var(--border) !important;\r\n  border-radius: var(--radius-xl) !important;\r\n  box-shadow: var(--shadow-md) !important;\r\n}\r\n\r\n.about-closing .ant-card-body {\r\n  padding: 48px 32px;\r\n  text-align: center;\r\n}\r\n\r\n.about-closing__content {\r\n  max-width: 760px;\r\n  margin: 0 auto;\r\n}\r\n\r\n.about-divider {\r\n  margin: 22px 0 18px !important;\r\n  border-color: var(--border) !important;\r\n}\r\n\r\n.tech-tag {\r\n  background: var(--surface-2) !important;\r\n  color: var(--text) !important;\r\n  border: 1px solid var(--border) !important;\r\n  border-radius: 999px !important;\r\n  padding: 6px 14px !important;\r\n  font-weight: 500 !important;\r\n  font-size: 12.5px !important;\r\n  margin: 0 !important;\r\n  transition: all 0.25s var(--ease-smooth);\r\n}\r\n\r\n.tech-tag:hover {\r\n  background: var(--accent-soft) !important;\r\n  color: var(--accent) !important;\r\n  border-color: var(--accent-ring) !important;\r\n  transform: translateY(-1px);\r\n}\r\n\r\n/* ============ Responsive ============ */\r\n\r\n/* Tablet portrait / mobile — container gap matches ProfilePage exactly.\r\n   The page's own padding is now the single source of the outer gap;\r\n   the hero and sections no longer add their own margin/padding on top\r\n   of it, so the edge-to-card distance lines up with .profile-page-container. */\r\n@media (max-width: 768px) {\r\n  .about-page {\r\n    padding: 14px;\r\n    padding-top: 8px;\r\n  }\r\n\r\n  .about-hero {\r\n    padding: 56px 20px 40px;\r\n    margin: 0;\r\n  }\r\n\r\n  .about-section {\r\n    padding: 0;\r\n  }\r\n\r\n  .about-card .ant-card-body {\r\n    padding: 22px;\r\n  }\r\n\r\n  .about-closing .ant-card-body {\r\n    padding: 36px 22px;\r\n  }\r\n\r\n  .about-hero__brand {\r\n    flex-direction: column;\r\n    gap: 10px;\r\n  }\r\n\r\n  .about-hero__brand-meta {\r\n    align-items: center;\r\n  }\r\n}\r\n\r\n/* Mobile */\r\n@media (max-width: 600px) {\r\n  .about-page {\r\n    padding: 12px;\r\n  }\r\n}\r\n\r\n@media (max-width: 480px) {\r\n  .about-page {\r\n    padding: 12px;\r\n  }\r\n\r\n  .about-hero {\r\n    padding: 48px 16px 32px;\r\n  }\r\n\r\n  .about-hero__title {\r\n    font-size: 30px !important;\r\n  }\r\n\r\n  .about-hero__lead {\r\n    font-size: 15px !important;\r\n  }\r\n\r\n  .stat-card {\r\n    padding: 12px;\r\n  }\r\n\r\n  .stat-value {\r\n    font-size: 16px;\r\n  }\r\n}\r\n\r\n@media (max-width: 360px) {\r\n  .about-page {\r\n    padding: 10px;\r\n  }\r\n\r\n  .about-hero {\r\n    padding: 40px 14px 28px;\r\n  }\r\n}\r\n\r\n/* Accessibility — reduced motion */\r\n@media (prefers-reduced-motion: reduce) {\r\n\r\n  .about-page,\r\n  .about-hero__content,\r\n  .about-section,\r\n  .feature-card,\r\n  .page-item,\r\n  .goal-item,\r\n  .about-hero__logo,\r\n  .orb,\r\n  .btn-primary-grad::after {\r\n    animation: none !important;\r\n    transition: none !important;\r\n  }\r\n}", ""]);
