___CSS_LOADER_EXPORT___.push([module.id, ".ann-page {\r\n    --ann-accent: #4f46e5;\r\n    --ann-accent-2: #7c3aed;\r\n    --ann-accent-soft: rgba(79, 70, 229, 0.1);\r\n    --ann-accent-ring: rgba(79, 70, 229, 0.22);\r\n    --ann-surface: #ffffff;\r\n    --ann-border: #e2e8f0;\r\n    --ann-text: #0b1220;\r\n    --ann-text-muted: #5b6677;\r\n    --ann-shadow-sm: 0 4px 14px rgba(2, 6, 23, 0.06);\r\n    --ann-shadow-md: 0 14px 34px rgba(2, 6, 23, 0.1);\r\n\r\n    padding: 24px;\r\n    max-width: 1200px;\r\n    margin: 0 auto;\r\n}\r\n\r\n[data-theme=\"black\"] .ann-page {\r\n    --ann-surface: #171a23;\r\n    --ann-border: #2a2e3a;\r\n    --ann-text: #e7e9ee;\r\n    --ann-text-muted: #9aa3b2;\r\n    --ann-accent-ring: rgba(124, 58, 237, 0.3);\r\n}\r\n\r\n/* ===== Hero — copied verbatim from AlumniEvents.css for visual consistency ===== */\r\n.alumni-events-container {\r\n    padding: 24px;\r\n    padding-top: 10px;\r\n    min-height: 100vh;\r\n    position: relative;\r\n    z-index: 1;\r\n}\r\n\r\n.ae-hero {\r\n    --ae-ease-spring: cubic-bezier(0.22, 1, 0.36, 1);\r\n    --ae-ease-smooth: cubic-bezier(0.4, 0, 0.2, 1);\r\n    --ae-accent: #0ea5e9;\r\n    --ae-accent-2: #14b8a6;\r\n    --ae-accent-3: #6366f1;\r\n    --ae-accent-soft: rgba(14, 165, 233, 0.1);\r\n    --ae-accent-ring: rgba(14, 165, 233, 0.28);\r\n    --ae-surface: #ffffff;\r\n    --ae-border: #e2e8f0;\r\n    --ae-text: #0b1220;\r\n    --ae-text-muted: #5b6677;\r\n    --ae-shadow-sm: 0 4px 14px rgba(2, 6, 23, 0.06);\r\n    --ae-shadow-md: 0 14px 34px rgba(2, 6, 23, 0.1);\r\n\r\n    position: relative;\r\n    overflow: hidden;\r\n    border-radius: 26px;\r\n    background:\r\n        linear-gradient(180deg, var(--ae-surface), var(--ae-surface))\r\n            padding-box,\r\n        linear-gradient(\r\n                135deg,\r\n                rgba(14, 165, 233, 0.45),\r\n                rgba(99, 102, 241, 0.35),\r\n                rgba(20, 184, 166, 0.45)\r\n            )\r\n            border-box;\r\n    border: 1px solid transparent;\r\n    box-shadow: var(--ae-shadow-md);\r\n    opacity: 0;\r\n    transform: translateY(8px);\r\n    animation: aeFadeUp 0.7s var(--ae-ease-spring) forwards;\r\n}\r\n\r\n@keyframes aeFadeUp {\r\n    to {\r\n        opacity: 1;\r\n        transform: translateY(0);\r\n    }\r\n}\r\n@keyframes aeFloat {\r\n    0%,\r\n    100% {\r\n        transform: translateY(0) scale(1);\r\n    }\r\n    50% {\r\n        transform: translateY(-14px) scale(1.04);\r\n    }\r\n}\r\n\r\n.ae-hero__bg {\r\n    position: absolute;\r\n    inset: 0;\r\n    pointer-events: none;\r\n    overflow: hidden;\r\n}\r\n.ae-hero__bg .blob {\r\n    position: absolute;\r\n    border-radius: 50%;\r\n    filter: blur(70px);\r\n    opacity: 0.5;\r\n    animation: aeFloat 14s ease-in-out infinite;\r\n}\r\n.ae-hero__bg .blob-1 {\r\n    width: 280px;\r\n    height: 280px;\r\n    background: #38bdf8;\r\n    top: -70px;\r\n    left: -50px;\r\n}\r\n.ae-hero__bg .blob-2 {\r\n    width: 320px;\r\n    height: 320px;\r\n    background: #6366f1;\r\n    bottom: -130px;\r\n    right: -70px;\r\n    animation-duration: 18s;\r\n}\r\n.ae-hero__bg .blob-3 {\r\n    width: 200px;\r\n    height: 200px;\r\n    background: #14b8a6;\r\n    top: 40%;\r\n    left: 55%;\r\n    animation-duration: 22s;\r\n    opacity: 0.35;\r\n}\r\n.ae-hero__bg .dot-grid {\r\n    position: absolute;\r\n    inset: 0;\r\n    background-image: radial-gradient(\r\n        rgba(15, 23, 42, 0.08) 1px,\r\n        transparent 1px\r\n    );\r\n    background-size: 18px 18px;\r\n    -webkit-mask-image: radial-gradient(\r\n        ellipse at center,\r\n        black 30%,\r\n        transparent 75%\r\n    );\r\n    mask-image: radial-gradient(ellipse at center, black 30%, transparent 75%);\r\n}\r\n\r\n.ae-hero__content {\r\n    position: relative;\r\n    z-index: 1;\r\n    max-width: 1080px;\r\n    margin: 0 auto;\r\n    text-align: center;\r\n    /* Horizontal-only safe padding, kept >= .ae-hero's border-radius (26px\r\n       at base) so nothing inside — like the right-column stat tiles — ever\r\n       sits in the corner zone that .ae-hero's overflow:hidden rounds off\r\n       and visually clips. Vertical spacing is handled per breakpoint. */\r\n    padding: 0 28px;\r\n}\r\n\r\n.ae-hero__brand {\r\n    display: inline-flex;\r\n    align-items: center;\r\n    gap: 14px;\r\n    margin-bottom: 14px;\r\n}\r\n.ae-hero__logo {\r\n    width: 56px;\r\n    height: 56px;\r\n    -o-object-fit: contain;\r\n       object-fit: contain;\r\n    border-radius: 14px;\r\n    background: var(--ae-surface);\r\n    padding: 6px;\r\n    box-shadow: var(--ae-shadow-sm);\r\n    animation: aeFloat 6s ease-in-out infinite;\r\n}\r\n.ae-hero__brand-meta {\r\n    display: flex;\r\n    flex-direction: column;\r\n    align-items: flex-start;\r\n    gap: 4px;\r\n}\r\n.ae-chip {\r\n    background: var(--ae-accent-soft) !important;\r\n    color: var(--ae-accent) !important;\r\n    border: 1px solid var(--ae-accent-ring) !important;\r\n    border-radius: 999px !important;\r\n    padding: 4px 12px !important;\r\n    font-weight: 700 !important;\r\n    font-size: 11.5px !important;\r\n    letter-spacing: 0.08em;\r\n    margin: 0 !important;\r\n}\r\n.ae-hero__eyebrow {\r\n    color: var(--ae-text-muted) !important;\r\n    font-size: 13px;\r\n    letter-spacing: 0.08em;\r\n    text-transform: uppercase;\r\n}\r\n.ae-hero__title {\r\n    font-size: clamp(28px, 4.4vw, 46px) !important;\r\n    line-height: 1.1 !important;\r\n    font-weight: 800 !important;\r\n    letter-spacing: -0.02em;\r\n    color: var(--ae-text) !important;\r\n    margin: 6px 0 14px !important;\r\n}\r\n.ae-hero .grad-text {\r\n    background: linear-gradient(\r\n        135deg,\r\n        var(--ae-accent) 0%,\r\n        var(--ae-accent-3) 50%,\r\n        var(--ae-accent-2) 100%\r\n    );\r\n    -webkit-background-clip: text;\r\n    background-clip: text;\r\n    -webkit-text-fill-color: transparent;\r\n    color: transparent;\r\n}\r\n.ae-hero__lead {\r\n    color: var(--ae-text-muted) !important;\r\n    font-size: 16px !important;\r\n    line-height: 1.7 !important;\r\n    max-width: 720px;\r\n    margin: 0 auto 28px !important;\r\n}\r\n\r\n/* Stat tiles */\r\n.ae-hero__stats {\r\n    display: grid;\r\n    grid-template-columns: repeat(4, minmax(0, 1fr));\r\n    gap: 14px;\r\n    max-width: 920px;\r\n    margin: 0 auto;\r\n}\r\n.ae-stat {\r\n    display: flex;\r\n    align-items: center;\r\n    gap: 14px;\r\n    padding: 16px 18px;\r\n    background: rgba(255, 255, 255, 0.85);\r\n    backdrop-filter: blur(10px);\r\n    -webkit-backdrop-filter: blur(10px);\r\n    border: 1px solid var(--ae-border);\r\n    border-radius: 16px;\r\n    box-shadow: var(--ae-shadow-sm);\r\n    text-align: left;\r\n    /* As a grid item, .ae-stat's default min-width is \"auto\", which floors\r\n       it at its content's intrinsic width regardless of the minmax(0, 1fr)\r\n       track it sits in. That's what was forcing the right-column tiles\r\n       (\"Published\", \"Categories\") past the hero card's edge and getting\r\n       clipped by its overflow:hidden — this lets the flexbox row (icon +\r\n       label) actually shrink/wrap instead of pushing the grid wider. */\r\n    min-width: 0;\r\n    transition:\r\n        transform 0.25s var(--ae-ease-spring),\r\n        box-shadow 0.25s var(--ae-ease-smooth),\r\n        border-color 0.25s;\r\n}\r\n.ae-stat:hover {\r\n    transform: translateY(-3px);\r\n    border-color: var(--ae-accent-ring);\r\n    box-shadow: var(--ae-shadow-md);\r\n}\r\n.ae-stat__icon {\r\n    display: inline-flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    width: 42px;\r\n    height: 42px;\r\n    border-radius: 12px;\r\n    background: var(--ae-accent-soft);\r\n    color: var(--ae-accent);\r\n    font-size: 18px;\r\n    flex-shrink: 0;\r\n}\r\n.ae-stat__icon--blue {\r\n    background: rgba(99, 102, 241, 0.12);\r\n    color: #6366f1;\r\n}\r\n.ae-stat__icon--green {\r\n    background: rgba(16, 185, 129, 0.12);\r\n    color: #10b981;\r\n}\r\n.ae-stat__icon--gray {\r\n    background: rgba(100, 116, 139, 0.12);\r\n    color: #64748b;\r\n}\r\n.ae-stat__body {\r\n    display: flex;\r\n    flex-direction: column;\r\n    line-height: 1.2;\r\n    min-width: 0;\r\n}\r\n.ae-stat__value {\r\n    font-size: 22px;\r\n    font-weight: 800;\r\n    color: var(--ae-text);\r\n    letter-spacing: -0.01em;\r\n    overflow-wrap: break-word;\r\n    word-break: break-word;\r\n}\r\n.ae-stat__label {\r\n    font-size: 12px;\r\n    color: var(--ae-text-muted);\r\n    margin-top: 2px;\r\n    font-weight: 500;\r\n    overflow-wrap: break-word;\r\n    word-break: break-word;\r\n}\r\n\r\n/* Responsive */\r\n@media (max-width: 900px) {\r\n    .ae-hero__stats {\r\n        grid-template-columns: repeat(2, minmax(0, 1fr));\r\n    }\r\n}\r\n@media (max-width: 560px) {\r\n    .ae-hero {\r\n        /* Horizontal padding now lives on .ae-hero__content (see base\r\n           rule) so it can't fall out of sync with border-radius again;\r\n           this only needs to add the extra vertical breathing room. */\r\n        padding: 40px 0 28px;\r\n        border-radius: 20px;\r\n    }\r\n    .ae-hero__brand {\r\n        flex-direction: column;\r\n        gap: 10px;\r\n    }\r\n    .ae-hero__brand-meta {\r\n        align-items: center;\r\n    }\r\n    .ae-hero__title {\r\n        font-size: 26px !important;\r\n    }\r\n    .ae-hero__lead {\r\n        font-size: 14.5px !important;\r\n    }\r\n}\r\n\r\n@media (prefers-reduced-motion: reduce) {\r\n    .ae-hero,\r\n    .ae-hero__logo,\r\n    .ae-hero__bg .blob {\r\n        animation: none !important;\r\n    }\r\n    .ae-stat {\r\n        transition: none;\r\n    }\r\n}\r\n\r\n/* Dark theme — matches AlumniEvents.css black theme for the hero */\r\n[data-theme=\"black\"] .ae-hero {\r\n    --ae-surface: #121620;\r\n    --ae-border: #242a36;\r\n    --ae-text: #e7ecf3;\r\n    --ae-text-muted: #9aa4b2;\r\n    --ae-accent-soft: rgba(14, 165, 233, 0.16);\r\n    --ae-shadow-sm: 0 4px 14px rgba(0, 0, 0, 0.45);\r\n    --ae-shadow-md: 0 14px 34px rgba(0, 0, 0, 0.55);\r\n\r\n    background:\r\n        linear-gradient(180deg, #121620, #121620) padding-box,\r\n        linear-gradient(\r\n                135deg,\r\n                rgba(14, 165, 233, 0.55),\r\n                rgba(99, 102, 241, 0.45),\r\n                rgba(20, 184, 166, 0.55)\r\n            )\r\n            border-box;\r\n}\r\n[data-theme=\"black\"] .ae-hero__bg .dot-grid {\r\n    background-image: radial-gradient(\r\n        rgba(255, 255, 255, 0.08) 1px,\r\n        transparent 1px\r\n    );\r\n}\r\n[data-theme=\"black\"] .ae-stat {\r\n    background: rgba(26, 31, 43, 0.85);\r\n    border-color: #242a36;\r\n}\r\n[data-theme=\"black\"] .ae-stat__value {\r\n    color: #e7ecf3;\r\n}\r\n[data-theme=\"black\"] .ae-hero__logo {\r\n    background: #1a1f2b;\r\n}\r\n\r\n/* ===== New-announcement button, placed in the toolbar row ===== */\r\n.ann-new-btn {\r\n    border-radius: 12px !important;\r\n}\r\n\r\n/* ===== Toolbar ===== */\r\n.ann-toolbar {\r\n    display: flex;\r\n    gap: 12px;\r\n    margin-bottom: 20px;\r\n    flex-wrap: wrap;\r\n}\r\n\r\n.ann-search {\r\n    flex: 1;\r\n    min-width: 220px;\r\n    /* Without a ceiling, flex:1 lets this grow to fill whatever's left in\r\n       the toolbar — on the alumni view specifically, which only has one\r\n       filter dropdown next to it (no status filter, no New Announcement\r\n       button), that meant the search box stretched almost the full width\r\n       of the page on desktop. */\r\n    max-width: 420px;\r\n    border-radius: 10px;\r\n}\r\n\r\n.ann-filter {\r\n    min-width: 170px;\r\n}\r\n\r\n/* ===== Grid ===== */\r\n.ann-grid {\r\n    display: grid;\r\n    grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));\r\n    gap: 18px;\r\n    transition: opacity 0.2s ease;\r\n}\r\n\r\n.ann-grid-fetching {\r\n    opacity: 0.6;\r\n}\r\n\r\n.ann-loading,\r\n.ann-empty {\r\n    padding: 80px 0;\r\n    display: flex;\r\n    justify-content: center;\r\n}\r\n\r\n/* ===== Card ===== */\r\n.ann-card {\r\n    position: relative;\r\n    background: var(--ann-surface);\r\n    border: 1px solid var(--ann-border);\r\n    border-radius: 16px;\r\n    overflow: hidden;\r\n    cursor: pointer;\r\n    box-shadow: var(--ann-shadow-sm);\r\n    transition: transform 0.2s ease, box-shadow 0.2s ease;\r\n    display: flex;\r\n    flex-direction: column;\r\n}\r\n\r\n.ann-card:hover {\r\n    transform: translateY(-3px);\r\n    box-shadow: var(--ann-shadow-md);\r\n}\r\n\r\n.ann-card-pinned {\r\n    border-color: var(--ann-accent);\r\n}\r\n\r\n.ann-pin-badge {\r\n    position: absolute;\r\n    top: 12px;\r\n    left: 12px;\r\n    z-index: 2;\r\n    display: flex;\r\n    align-items: center;\r\n    gap: 4px;\r\n    font-size: 12px;\r\n    font-weight: 600;\r\n    color: #fff;\r\n    padding: 3px 10px;\r\n    border-radius: 999px;\r\n    background: linear-gradient(135deg, #f59e0b, #f97316);\r\n    box-shadow: 0 6px 16px rgba(245, 158, 11, 0.35);\r\n}\r\n\r\n/* Admin-only: flags a \"published\" announcement whose publish_date hasn't\r\n   arrived yet, so it doesn't look silently the same as one that's actually\r\n   visible to alumni. Sits opposite the pinned badge so the two never clash. */\r\n.ann-scheduled-badge {\r\n    position: absolute;\r\n    top: 12px;\r\n    right: 12px;\r\n    z-index: 2;\r\n    display: flex;\r\n    align-items: center;\r\n    gap: 4px;\r\n    font-size: 12px;\r\n    font-weight: 600;\r\n    color: #fff;\r\n    padding: 3px 10px;\r\n    border-radius: 999px;\r\n    background: linear-gradient(135deg, #2563eb, #38bdf8);\r\n    box-shadow: 0 6px 16px rgba(37, 99, 235, 0.35);\r\n}\r\n\r\n.ann-card-image {\r\n    height: 150px;\r\n    overflow: hidden;\r\n    background: #f1f5f9;\r\n}\r\n\r\n.ann-card-image img {\r\n    width: 100%;\r\n    height: 100%;\r\n    -o-object-fit: cover;\r\n       object-fit: cover;\r\n}\r\n\r\n/* ===== No-image placeholder (card + detail) ===== */\r\n.ann-card-image-placeholder {\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    font-size: 48px;\r\n    color: #fff;\r\n    background: linear-gradient(135deg, var(--ann-accent), var(--ann-accent-2));\r\n}\r\n\r\n.ann-detail-placeholder {\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    height: 160px;\r\n    border-radius: 14px;\r\n    margin: 16px 0;\r\n    font-size: 64px;\r\n    color: #fff;\r\n    background: linear-gradient(135deg, var(--ann-accent), var(--ann-accent-2));\r\n}\r\n\r\n/* Category-tinted gradients so placeholders aren't all identical */\r\n.ann-cat-general { background: linear-gradient(135deg, #64748b, #94a3b8); }\r\n.ann-cat-academic { background: linear-gradient(135deg, #2563eb, #60a5fa); }\r\n.ann-cat-event { background: linear-gradient(135deg, #7c3aed, #a78bfa); }\r\n.ann-cat-career { background: linear-gradient(135deg, #059669, #34d399); }\r\n.ann-cat-urgent { background: linear-gradient(135deg, #dc2626, #f87171); }\r\n.ann-cat-maintenance { background: linear-gradient(135deg, #ea580c, #fb923c); }\r\n.ann-cat-other { background: linear-gradient(135deg, #0891b2, #22d3ee); }\r\n\r\n.ann-card-body {\r\n    padding: 16px 18px;\r\n    display: flex;\r\n    flex-direction: column;\r\n    flex: 1;\r\n}\r\n\r\n.ann-card-tags {\r\n    display: flex;\r\n    gap: 6px;\r\n    margin-bottom: 8px;\r\n    flex-wrap: wrap;\r\n}\r\n\r\n.ann-card-title {\r\n    margin: 0 0 6px 0 !important;\r\n    color: var(--ann-text) !important;\r\n    font-size: 17px !important;\r\n}\r\n\r\n.ann-card-excerpt {\r\n    color: var(--ann-text-muted) !important;\r\n    margin-bottom: 12px !important;\r\n    flex: 1;\r\n}\r\n\r\n.ann-card-footer {\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: space-between;\r\n    margin-top: auto;\r\n    padding-top: 10px;\r\n    border-top: 1px solid var(--ann-border);\r\n}\r\n\r\n.ann-card-date {\r\n    font-size: 12px;\r\n    color: var(--ann-text-muted);\r\n    display: flex;\r\n    align-items: center;\r\n    gap: 6px;\r\n}\r\n\r\n.ann-card-actions {\r\n    display: flex;\r\n    align-items: center;\r\n    gap: 4px;\r\n}\r\n\r\n.ann-views {\r\n    font-size: 12px;\r\n    color: var(--ann-text-muted);\r\n    margin-right: 6px;\r\n    display: flex;\r\n    align-items: center;\r\n    gap: 4px;\r\n}\r\n\r\n.ann-read-more {\r\n    padding: 0 !important;\r\n    font-weight: 600;\r\n}\r\n\r\n/* ===== Form modal ===== */\r\n.ann-schedule-alert {\r\n    margin-bottom: 16px;\r\n    border-radius: 10px;\r\n}\r\n\r\n.ann-form-row {\r\n    display: flex;\r\n    gap: 12px;\r\n}\r\n\r\n.ann-form-col {\r\n    flex: 1;\r\n}\r\n\r\n/* ===== Detail modal ===== */\r\n.ann-detail-tags {\r\n    display: flex;\r\n    gap: 8px;\r\n    margin-bottom: 10px;\r\n}\r\n\r\n.ann-detail-images {\r\n    display: flex;\r\n    gap: 10px;\r\n    margin: 16px 0;\r\n    flex-wrap: wrap;\r\n}\r\n\r\n.ann-detail-content {\r\n    margin-top: 16px !important;\r\n    white-space: pre-line;\r\n    color: var(--ann-text);\r\n}\r\n\r\n/* ======================================================================\r\n   MOBILE RESPONSIVENESS — portrait, landscape, and small phones\r\n   ====================================================================== */\r\n\r\n/* ---- Tablets / large phones, portrait ---- */\r\n@media (max-width: 768px) {\r\n    .ann-page,\r\n    .alumni-events-container {\r\n        padding: 16px;\r\n        padding-top: 8px;\r\n    }\r\n\r\n    .ann-grid {\r\n        grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));\r\n        gap: 14px;\r\n    }\r\n}\r\n\r\n/* ---- Phones, portrait (roughly iPhone/Android widths) ---- */\r\n@media (max-width: 600px) {\r\n    .ann-toolbar {\r\n        flex-direction: column;\r\n        align-items: stretch;\r\n        gap: 14px;\r\n    }\r\n\r\n    .ann-search,\r\n    .ann-filter,\r\n    .ann-new-btn {\r\n        width: 100%;\r\n        min-width: 0;\r\n    }\r\n\r\n    /* Belt-and-suspenders spacing: guarantees a visible gap between the\r\n       search box, the category/status filters, and the New Announcement\r\n       button when stacked, even if something else on the page collapses\r\n       the flex `gap` above. :not(:last-child) means whichever control\r\n       ends up last (the status filter and button only render for admins)\r\n       never gets an unwanted trailing margin before the grid below. */\r\n    .ann-toolbar > *:not(:last-child) {\r\n        margin-bottom: 14px;\r\n    }\r\n\r\n    .ann-grid {\r\n        grid-template-columns: 1fr;\r\n    }\r\n\r\n    .ae-hero__stats {\r\n        grid-template-columns: repeat(2, minmax(0, 1fr));\r\n    }\r\n\r\n    .ann-form-row {\r\n        flex-direction: column;\r\n        gap: 0;\r\n    }\r\n\r\n    .ann-card-footer {\r\n        flex-wrap: wrap;\r\n        gap: 8px;\r\n    }\r\n}\r\n\r\n/* ---- Small / narrow phones (SE, small Android, folded devices) ---- */\r\n@media (max-width: 380px) {\r\n    .ann-page,\r\n    .alumni-events-container {\r\n        padding: 12px;\r\n        padding-top: 6px;\r\n    }\r\n\r\n    .ae-hero__stats {\r\n        grid-template-columns: 1fr;\r\n    }\r\n\r\n    .ae-hero__title {\r\n        font-size: 22px !important;\r\n    }\r\n\r\n    .ann-card-image,\r\n    .ann-card-image-placeholder {\r\n        height: 120px;\r\n    }\r\n\r\n    .ann-card-image-placeholder {\r\n        font-size: 34px;\r\n    }\r\n\r\n    .ann-detail-placeholder {\r\n        height: 120px;\r\n        font-size: 44px;\r\n    }\r\n}\r\n\r\n/* ---- Phones in LANDSCAPE (short viewport height, not just narrow width) ---- */\r\n@media (orientation: landscape) and (max-height: 500px) {\r\n    .ann-page,\r\n    .alumni-events-container {\r\n        padding: 10px 16px;\r\n        padding-top: 6px;\r\n    }\r\n\r\n    /* Previously this block also hid .ae-hero__bg entirely and zeroed\r\n       .ae-hero__content's padding, which is what caused two separate bugs:\r\n       (1) the hero looking flat grey/black here instead of matching the\r\n       gradient-glow look used everywhere else, and (2) the right-column\r\n       stat tiles (\"Published\", \"Categories\") getting visually clipped by\r\n       the hero's own rounded corners once their horizontal safe-padding\r\n       was zeroed out. Neither override is needed — the blobs are\r\n       absolutely positioned so they don't consume any vertical space, and\r\n       .ae-hero__content's base padding (0 28px, see base rule) already\r\n       has zero top/bottom padding, so there's nothing left to override\r\n       here for either concern. */\r\n\r\n    .ae-hero__brand {\r\n        margin-bottom: 8px;\r\n    }\r\n\r\n    .ae-hero__logo {\r\n        width: 40px;\r\n        height: 40px;\r\n    }\r\n\r\n    .ae-hero__title {\r\n        font-size: 22px !important;\r\n        margin: 4px 0 8px !important;\r\n    }\r\n\r\n    .ae-hero__lead {\r\n        font-size: 13px !important;\r\n        margin: 0 auto 14px !important;\r\n    }\r\n\r\n    .ae-hero__stats {\r\n        grid-template-columns: repeat(4, minmax(0, 1fr));\r\n        gap: 8px;\r\n    }\r\n\r\n    .ae-stat {\r\n        padding: 8px 10px;\r\n        gap: 8px;\r\n    }\r\n\r\n    .ae-stat__icon {\r\n        width: 32px;\r\n        height: 32px;\r\n        font-size: 14px;\r\n    }\r\n\r\n    .ae-stat__value {\r\n        font-size: 16px;\r\n    }\r\n\r\n    .ae-stat__label {\r\n        font-size: 10px;\r\n    }\r\n\r\n    .ann-grid {\r\n        grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));\r\n    }\r\n\r\n    .ann-card-image,\r\n    .ann-card-image-placeholder {\r\n        height: 100px;\r\n    }\r\n}\r\n\r\n/* ---- Modals: full-width-ish on phones, scrollable body so nothing gets\r\n   cut off in short landscape viewports ---- */\r\n.ann-modal .ant-modal-content {\r\n    border-radius: 16px;\r\n    overflow: hidden;\r\n}\r\n\r\n@media (max-width: 600px) {\r\n    .ann-modal.ant-modal {\r\n        max-width: calc(100vw - 24px);\r\n        top: 16px;\r\n        padding-bottom: 16px;\r\n        margin: 0 auto;\r\n    }\r\n\r\n    .ann-modal .ant-modal-body {\r\n        max-height: 70vh;\r\n        overflow-y: auto;\r\n    }\r\n\r\n    .ann-form-col .ant-picker,\r\n    .ann-form-col .ant-select {\r\n        width: 100% !important;\r\n    }\r\n}\r\n\r\n@media (orientation: landscape) and (max-height: 500px) {\r\n    .ann-modal.ant-modal {\r\n        top: 8px;\r\n        max-width: calc(100vw - 16px);\r\n    }\r\n\r\n    .ann-modal .ant-modal-body {\r\n        max-height: 78vh;\r\n        overflow-y: auto;\r\n        padding: 14px 16px;\r\n    }\r\n\r\n    .ann-detail-modal .ant-modal-body {\r\n        max-height: 82vh;\r\n    }\r\n}\r\n\r\n/* Upload picture-card shrinks a bit on narrow screens so 2 thumbnails\r\n   still fit per row instead of overflowing. */\r\n@media (max-width: 380px) {\r\n    .ann-modal .ant-upload.ant-upload-select-picture-card,\r\n    .ann-modal .ant-upload-list-picture-card .ant-upload-list-item {\r\n        width: 76px !important;\r\n        height: 76px !important;\r\n    }\r\n}", ""]);
