___CSS_LOADER_EXPORT___.push([module.id, "/* ============================================================\r\n   Change Password Modal — Premium Animated UI\r\n   ============================================================ */\r\n\r\n.change-password-modal .ant-modal-content {\r\n    padding: 0;\r\n    overflow: hidden;\r\n    border-radius: 20px;\r\n    box-shadow:\r\n        0 24px 60px -12px rgba(24, 144, 255, 0.25),\r\n        0 12px 30px -8px rgba(114, 46, 209, 0.18),\r\n        0 0 0 1px rgba(255, 255, 255, 0.6) inset;\r\n    animation: cpModalIn 0.5s cubic-bezier(0.22, 1, 0.36, 1);\r\n    background: #ffffff;\r\n}\r\n\r\n@keyframes cpModalIn {\r\n    0%   { opacity: 0; transform: translateY(24px) scale(0.96); }\r\n    60%  { opacity: 1; transform: translateY(-4px) scale(1.01); }\r\n    100% { opacity: 1; transform: translateY(0)    scale(1);    }\r\n}\r\n\r\n.change-password-modal .ant-modal-mask {\r\n    -webkit-backdrop-filter: blur(6px);\r\n            backdrop-filter: blur(6px);\r\n    background: rgba(15, 23, 42, 0.45);\r\n    animation: cpFadeIn 0.35s ease;\r\n}\r\n\r\n@keyframes cpFadeIn { from { opacity: 0; } to { opacity: 1; } }\r\n\r\n.change-password-modal .ant-modal-close {\r\n    top: 18px;\r\n    right: 18px;\r\n    z-index: 10;\r\n    transition: transform 0.25s ease, background 0.25s ease;\r\n    border-radius: 50%;\r\n    width: 32px;\r\n    height: 32px;\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n}\r\n.change-password-modal .ant-modal-close:hover {\r\n    background: rgba(255, 255, 255, 0.22);\r\n    transform: rotate(90deg) scale(1.08);\r\n}\r\n\r\n/* ============ Header ============ */\r\n.cp-header {\r\n    position: relative;\r\n    background: linear-gradient(135deg, var(--accent, #4f46e5) 0%, #4f46e5 50%, var(--accent-3, #7c3aed) 100%);\r\n    background-size: 200% 200%;\r\n    padding: 26px 28px;\r\n    display: flex;\r\n    align-items: center;\r\n    gap: 16px;\r\n    color: #fff;\r\n    overflow: hidden;\r\n    animation: cpGradientShift 8s ease infinite;\r\n}\r\n\r\n@keyframes cpGradientShift {\r\n    0%   { background-position: 0% 50%; }\r\n    50%  { background-position: 100% 50%; }\r\n    100% { background-position: 0% 50%; }\r\n}\r\n\r\n/* Floating glow blobs in header */\r\n.cp-header::before,\r\n.cp-header::after {\r\n    content: \"\";\r\n    position: absolute;\r\n    border-radius: 50%;\r\n    filter: blur(28px);\r\n    opacity: 0.55;\r\n    pointer-events: none;\r\n}\r\n.cp-header::before {\r\n    width: 160px; height: 160px;\r\n    background: rgba(255, 255, 255, 0.35);\r\n    top: -60px; right: -30px;\r\n    animation: cpFloat 7s ease-in-out infinite;\r\n}\r\n.cp-header::after {\r\n    width: 120px; height: 120px;\r\n    background: rgba(168, 85, 247, 0.55);\r\n    bottom: -50px; left: 30%;\r\n    animation: cpFloat 9s ease-in-out infinite reverse;\r\n}\r\n\r\n@keyframes cpFloat {\r\n    0%, 100% { transform: translate(0, 0) scale(1); }\r\n    50%      { transform: translate(-12px, 16px) scale(1.08); }\r\n}\r\n\r\n.cp-header-icon {\r\n    width: 54px;\r\n    height: 54px;\r\n    border-radius: 16px;\r\n    background: rgba(255, 255, 255, 0.22);\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    font-size: 24px;\r\n    color: #fff;\r\n    -webkit-backdrop-filter: blur(10px);\r\n            backdrop-filter: blur(10px);\r\n    flex-shrink: 0;\r\n    box-shadow: 0 8px 22px rgba(0, 0, 0, 0.18), inset 0 0 0 1px rgba(255,255,255,0.25);\r\n    animation: cpKeyPulse 2.6s ease-in-out infinite;\r\n    position: relative;\r\n    z-index: 1;\r\n}\r\n\r\n@keyframes cpKeyPulse {\r\n    0%, 100% { transform: scale(1)    rotate(0deg);  box-shadow: 0 8px 22px rgba(0,0,0,0.18), 0 0 0 0 rgba(255,255,255,0.45); }\r\n    50%      { transform: scale(1.06) rotate(-6deg); box-shadow: 0 12px 28px rgba(0,0,0,0.22), 0 0 0 10px rgba(255,255,255,0); }\r\n}\r\n\r\n.cp-header-text {\r\n    min-width: 0;\r\n    flex: 1;\r\n    position: relative;\r\n    z-index: 1;\r\n    animation: cpSlideRight 0.6s 0.1s both cubic-bezier(0.22, 1, 0.36, 1);\r\n}\r\n\r\n@keyframes cpSlideRight {\r\n    from { opacity: 0; transform: translateX(-12px); }\r\n    to   { opacity: 1; transform: translateX(0); }\r\n}\r\n\r\n/* ============ Body ============ */\r\n.cp-body {\r\n    padding: 26px 28px 28px;\r\n    animation: cpFadeUp 0.55s 0.15s both ease;\r\n}\r\n\r\n@keyframes cpFadeUp {\r\n    from { opacity: 0; transform: translateY(10px); }\r\n    to   { opacity: 1; transform: translateY(0); }\r\n}\r\n\r\n.cp-account-card {\r\n    background: linear-gradient(135deg, #f5f9ff 0%, #eef4ff 100%);\r\n    border: 1px solid #e6f0ff;\r\n    border-radius: 12px;\r\n    word-break: break-word;\r\n    transition: transform 0.25s ease, box-shadow 0.25s ease;\r\n}\r\n.cp-account-card:hover {\r\n    transform: translateY(-2px);\r\n    box-shadow: 0 10px 24px -10px rgba(24, 144, 255, 0.35);\r\n}\r\n\r\n/* ============ Form fields ============ */\r\n.change-password-modal .ant-form-item {\r\n    animation: cpFadeUp 0.5s both ease;\r\n}\r\n.change-password-modal .ant-form-item:nth-of-type(1) { animation-delay: 0.18s; }\r\n.change-password-modal .ant-form-item:nth-of-type(2) { animation-delay: 0.26s; }\r\n.change-password-modal .ant-form-item:nth-of-type(3) { animation-delay: 0.34s; }\r\n\r\n.change-password-modal .ant-input-affix-wrapper {\r\n    border-radius: 10px;\r\n    transition: all 0.25s ease;\r\n}\r\n.change-password-modal .ant-input-affix-wrapper:hover {\r\n    border-color: #4f46e5;\r\n}\r\n.change-password-modal .ant-input-affix-wrapper-focused {\r\n    box-shadow: 0 0 0 4px rgba(79, 70, 229, 0.12) !important;\r\n    border-color: #4f46e5 !important;\r\n    transform: translateY(-1px);\r\n}\r\n.change-password-modal .ant-input-prefix {\r\n    color: #4f46e5;\r\n    margin-right: 10px;\r\n    transition: transform 0.25s ease;\r\n}\r\n.change-password-modal .ant-input-affix-wrapper-focused .ant-input-prefix {\r\n    transform: scale(1.15);\r\n}\r\n\r\n/* ============ Strength meter ============ */\r\n.cp-strength {\r\n    margin: -8px 0 18px;\r\n    animation: cpFadeUp 0.4s ease;\r\n}\r\n.cp-strength-row {\r\n    display: flex;\r\n    justify-content: space-between;\r\n    margin-bottom: 6px;\r\n}\r\n.cp-strength .ant-progress-bg {\r\n    transition: width 0.5s cubic-bezier(0.22, 1, 0.36, 1), background 0.3s ease !important;\r\n    box-shadow: 0 0 8px currentColor;\r\n}\r\n\r\n/* ============ Requirements card ============ */\r\n.cp-requirements-card {\r\n    background: linear-gradient(135deg, #fafafa 0%, #f4f6fb 100%);\r\n    border-radius: 12px;\r\n    margin-bottom: 22px;\r\n    border: 1px solid #eef0f5;\r\n    overflow: hidden;\r\n}\r\n\r\n.cp-requirement {\r\n    display: flex;\r\n    align-items: center;\r\n    gap: 8px;\r\n    padding: 4px 6px;\r\n    border-radius: 8px;\r\n    transition: background 0.25s ease, transform 0.25s ease;\r\n}\r\n.cp-requirement:hover {\r\n    background: rgba(79, 70, 229, 0.06);\r\n    transform: translateX(3px);\r\n}\r\n.cp-requirement .anticon {\r\n    transition: transform 0.35s cubic-bezier(0.34, 1.56, 0.64, 1);\r\n}\r\n.cp-requirement .anticon-check-circle {\r\n    animation: cpPop 0.45s cubic-bezier(0.34, 1.56, 0.64, 1);\r\n}\r\n\r\n@keyframes cpPop {\r\n    0%   { transform: scale(0.4) rotate(-30deg); opacity: 0; }\r\n    60%  { transform: scale(1.25) rotate(8deg); }\r\n    100% { transform: scale(1) rotate(0); opacity: 1; }\r\n}\r\n\r\n/* ============ Actions ============ */\r\n.cp-actions {\r\n    display: flex;\r\n    flex-wrap: wrap;\r\n    justify-content: flex-end;\r\n    gap: 12px;\r\n    border-top: 1px solid #f0f0f0;\r\n    margin-top: 8px;\r\n    padding-top: 20px;\r\n}\r\n\r\n.cp-actions .ant-btn {\r\n    border-radius: 10px;\r\n    height: 44px;\r\n    font-weight: 600;\r\n    transition: all 0.3s cubic-bezier(0.22, 1, 0.36, 1);\r\n}\r\n.cp-actions .ant-btn:hover {\r\n    transform: translateY(-2px);\r\n}\r\n.cp-actions .ant-btn-primary {\r\n    background: linear-gradient(135deg, var(--accent, #4f46e5) 0%, #4f46e5 50%, var(--accent-3, #7c3aed) 100%);\r\n    background-size: 200% 200%;\r\n    border: none;\r\n    box-shadow: 0 8px 20px -6px rgba(79, 70, 229, 0.55);\r\n    animation: cpGradientShift 6s ease infinite;\r\n}\r\n.cp-actions .ant-btn-primary:hover {\r\n    box-shadow: 0 12px 28px -6px rgba(79, 70, 229, 0.7);\r\n    filter: brightness(1.05);\r\n}\r\n.cp-actions .ant-btn-primary:active {\r\n    transform: translateY(0) scale(0.98);\r\n}\r\n\r\n/* Shake on form validation error */\r\n.change-password-modal .ant-form-item-has-error .ant-input-affix-wrapper {\r\n    animation: cpShake 0.45s cubic-bezier(0.36, 0.07, 0.19, 0.97);\r\n}\r\n@keyframes cpShake {\r\n    10%, 90%  { transform: translateX(-2px); }\r\n    20%, 80%  { transform: translateX(3px); }\r\n    30%, 50%, 70% { transform: translateX(-5px); }\r\n    40%, 60%  { transform: translateX(5px); }\r\n}\r\n\r\n/* ============ Responsive: Tablets ============ */\r\n@media (max-width: 768px) {\r\n    .change-password-modal {\r\n        max-width: 95vw;\r\n        margin: 0 auto;\r\n    }\r\n    .change-password-modal .ant-modal-content {\r\n        border-radius: 16px;\r\n    }\r\n    .cp-header {\r\n        padding: 22px 20px;\r\n        gap: 12px;\r\n    }\r\n    .cp-header-icon {\r\n        width: 48px;\r\n        height: 48px;\r\n        font-size: 20px;\r\n        border-radius: 13px;\r\n    }\r\n    .cp-body {\r\n        padding: 22px 20px 24px;\r\n    }\r\n}\r\n\r\n/* ============ Responsive: Phones ============ */\r\n@media (max-width: 576px) {\r\n    .change-password-modal {\r\n        max-width: 100vw;\r\n        top: 0 !important;\r\n        padding-bottom: 0;\r\n        margin: 0;\r\n    }\r\n    .change-password-modal .ant-modal-content {\r\n        border-radius: 14px;\r\n        min-height: auto;\r\n    }\r\n    .change-password-modal .ant-modal-close {\r\n        top: 14px;\r\n        right: 14px;\r\n        width: 28px;\r\n        height: 28px;\r\n    }\r\n    .cp-header {\r\n        padding: 18px 16px;\r\n        gap: 10px;\r\n    }\r\n    .cp-header-icon {\r\n        width: 44px;\r\n        height: 44px;\r\n        font-size: 18px;\r\n        border-radius: 11px;\r\n    }\r\n    .cp-header h4.ant-typography {\r\n        font-size: 16px !important;\r\n    }\r\n    .cp-header .ant-typography {\r\n        font-size: 12px;\r\n    }\r\n    .cp-body {\r\n        padding: 16px 16px 20px;\r\n    }\r\n    .cp-account-card .ant-card-body {\r\n        padding: 10px 12px;\r\n    }\r\n    .cp-strength {\r\n        margin: -4px 0 14px;\r\n    }\r\n    .cp-requirements-card .ant-col {\r\n        flex: 0 0 100%;\r\n        max-width: 100%;\r\n    }\r\n    .cp-requirements-card .ant-card-head {\r\n        padding: 0 12px;\r\n        min-height: 36px;\r\n    }\r\n    .cp-requirements-card .ant-card-head-title {\r\n        padding: 8px 0;\r\n        font-size: 13px;\r\n    }\r\n    .cp-requirements-card .ant-card-body {\r\n        padding: 12px;\r\n    }\r\n    .cp-actions {\r\n        flex-direction: column-reverse;\r\n        gap: 10px;\r\n    }\r\n    .cp-actions .ant-btn {\r\n        width: 100%;\r\n        height: 46px;\r\n    }\r\n    .change-password-modal .ant-input-affix-wrapper-lg,\r\n    .change-password-modal .ant-input-lg {\r\n        font-size: 15px;\r\n    }\r\n    .change-password-modal .ant-form-item-label > label {\r\n        font-size: 13px;\r\n    }\r\n}\r\n\r\n/* ============ Responsive: Small phones ============ */\r\n@media (max-width: 360px) {\r\n    .cp-header {\r\n        padding: 16px 14px;\r\n    }\r\n    .cp-body {\r\n        padding: 14px 14px 18px;\r\n    }\r\n    .cp-header h4.ant-typography {\r\n        font-size: 15px !important;\r\n    }\r\n    .cp-header-icon {\r\n        width: 40px;\r\n        height: 40px;\r\n        font-size: 17px;\r\n    }\r\n}\r\n\r\n/* ============ Reduced motion (accessibility) ============ */\r\n@media (prefers-reduced-motion: reduce) {\r\n    .change-password-modal *,\r\n    .change-password-modal *::before,\r\n    .change-password-modal *::after {\r\n        animation: none !important;\r\n        transition: none !important;\r\n    }\r\n}\r\n\r\n/* ============ Dark theme ============ */\r\n[data-theme=\"black\"] .change-password-modal .ant-modal-content {\r\n    background: #1f1f1f;\r\n}\r\n[data-theme=\"black\"] .cp-account-card {\r\n    background: linear-gradient(135deg, #2a2a2a 0%, #232735 100%);\r\n    border-color: #3a3a3a;\r\n}\r\n[data-theme=\"black\"] .cp-requirements-card {\r\n    background: linear-gradient(135deg, #262626 0%, #1f2330 100%);\r\n    border-color: #3a3a3a;\r\n}\r\n[data-theme=\"black\"] .cp-actions {\r\n    border-top-color: #303030;\r\n}\r\n\r\n\r\n/* ============================================================\r\n   Unified Modal Mask — mirrors LoginForm / AlumniRegistration\r\n   ============================================================ */\r\n.change-password-modal .ant-modal-mask {\r\n  background: var(--overlay, rgba(2, 6, 23, 0.55)) !important;\r\n}\r\n[data-theme=\"black\"] .change-password-modal .ant-modal-content {\r\n  background: var(--surface, #121620) !important;\r\n  color: var(--text, #e7ecf3);\r\n}\r\n[data-theme=\"black\"] .change-password-modal .ant-modal-content * {\r\n  color: var(--text, #e7ecf3);\r\n}\r\n\r\n/* ============================================================\r\n   Drawer variant — side-wrapper (mirrors AlumniDetails drawer)\r\n   ============================================================ */\r\n\r\n.change-password-drawer.ant-drawer .ant-drawer-content-wrapper {\r\n    box-shadow:\r\n        -24px 0 60px -12px rgba(24, 144, 255, 0.20),\r\n        -12px 0 30px -8px rgba(114, 46, 209, 0.18);\r\n    animation: cpDrawerIn 0.5s cubic-bezier(0.22, 1, 0.36, 1);\r\n}\r\n\r\n@keyframes cpDrawerIn {\r\n    0%   { transform: translateX(40px); opacity: 0; }\r\n    100% { transform: translateX(0);    opacity: 1; }\r\n}\r\n\r\n.change-password-drawer .ant-drawer-mask {\r\n    -webkit-backdrop-filter: blur(6px);\r\n            backdrop-filter: blur(6px);\r\n    background: rgba(15, 23, 42, 0.45);\r\n    animation: cpFadeIn 0.35s ease;\r\n}\r\n\r\n.change-password-drawer .ant-drawer-header {\r\n    padding: 14px 20px;\r\n    border-bottom: 1px solid #e2e8f0;\r\n    background: #ffffff;\r\n}\r\n\r\n.change-password-drawer .ant-drawer-title {\r\n    font-weight: 600;\r\n    color: #0b1220;\r\n}\r\n\r\n.change-password-drawer .ant-drawer-body {\r\n    padding: 0 !important;\r\n    background: #ffffff;\r\n    overflow-y: auto;\r\n}\r\n\r\n/* Make the gradient header span full drawer width */\r\n.change-password-drawer .cp-header {\r\n    border-radius: 0;\r\n    padding: 28px 28px;\r\n}\r\n\r\n.change-password-drawer .cp-body {\r\n    padding: 24px 24px 32px;\r\n}\r\n\r\n/* Responsive — full width on small screens */\r\n@media (max-width: 640px) {\r\n    .change-password-drawer.ant-drawer .ant-drawer-content-wrapper {\r\n        width: 100% !important;\r\n    }\r\n}\r\n", ""]);
