___CSS_LOADER_EXPORT___.push([module.id, "/* ==============================================\r\n   ImageQuizPage.css — Modern, Professional, User-Friendly\r\n   Alumni Tracing Management System (matches About/FAQ system)\r\n   ============================================== */\r\n.quiz-page {\r\n  --ease-spring: cubic-bezier(0.22, 1, 0.36, 1);\r\n  --ease-smooth: cubic-bezier(0.4, 0, 0.2, 1);\r\n\r\n  --accent:        #4f46e5;\r\n  --accent-2:      #0ea5e9;\r\n  --accent-3:      #7c3aed;\r\n  --accent-soft:   rgba(79, 70, 229, 0.10);\r\n  --accent-ring:   rgba(79, 70, 229, 0.26);\r\n\r\n  --bg:            #f4f7fb;\r\n  --surface:       #ffffff;\r\n  --surface-2:     #f1f5f9;\r\n  --border:        #e2e8f0;\r\n  --border-strong: #cbd5e1;\r\n\r\n  --text:         #0b1220;\r\n  --text-muted:   #5b6677;\r\n  --text-subtle:  #94a3b8;\r\n\r\n  --shadow-xs: 0 1px 2px  rgba(2, 6, 23, 0.05);\r\n  --shadow-sm: 0 4px 14px rgba(2, 6, 23, 0.06);\r\n  --shadow-md: 0 14px 34px rgba(2, 6, 23, 0.10);\r\n  --shadow-lg: 0 28px 60px rgba(2, 6, 23, 0.18);\r\n\r\n  --radius-sm: 10px;\r\n  --radius-md: 14px;\r\n  --radius-lg: 18px;\r\n  --radius-xl: 26px;\r\n\r\n  background:\r\n    radial-gradient(900px 500px at 100% -10%, rgba(14, 165, 233, 0.10), transparent 60%),\r\n    radial-gradient(900px 500px at -10% 110%, rgba(124, 58, 237, 0.10), transparent 60%),\r\n    var(--bg);\r\n  color: var(--text);\r\n  min-height: 100vh;\r\n  padding: 0 0 72px;\r\n  font-family: -apple-system, BlinkMacSystemFont, \"Inter\", \"Segoe UI\", Roboto,\r\n    \"Helvetica Neue\", Arial, sans-serif;\r\n  opacity: 0;\r\n  transform: translateY(8px);\r\n  transition: opacity 0.6s var(--ease-smooth), transform 0.6s var(--ease-smooth);\r\n}\r\n.quiz-page.is-revealed { opacity: 1; transform: translateY(0); }\r\n\r\n[data-theme=\"black\"] .quiz-page {\r\n  --bg:            #0a0c12;\r\n  --surface:       #121620;\r\n  --surface-2:     #1a1f2b;\r\n  --border:        #242a36;\r\n  --border-strong: #303746;\r\n\r\n  --text:          #e7ecf3;\r\n  --text-muted:    #9aa4b2;\r\n  --text-subtle:   #6b7280;\r\n\r\n  --accent-soft:   rgba(99, 102, 241, 0.16);\r\n  --accent-ring:   rgba(99, 102, 241, 0.30);\r\n\r\n  --shadow-xs: 0 1px 2px  rgba(0, 0, 0, 0.5);\r\n  --shadow-sm: 0 4px 14px rgba(0, 0, 0, 0.45);\r\n  --shadow-md: 0 14px 34px rgba(0, 0, 0, 0.55);\r\n  --shadow-lg: 0 28px 60px rgba(0, 0, 0, 0.65);\r\n\r\n  background:\r\n    radial-gradient(900px 500px at 100% -10%, rgba(14, 165, 233, 0.10), transparent 60%),\r\n    radial-gradient(900px 500px at -10% 110%, rgba(124, 58, 237, 0.12), transparent 60%),\r\n    var(--bg);\r\n}\r\n\r\n@keyframes quizFadeUp { from { opacity:0; transform: translateY(14px);} to { opacity:1; transform: translateY(0);} }\r\n@keyframes quizFloat { 0%,100% { transform: translateY(0) scale(1);} 50% { transform: translateY(-12px) scale(1.04);} }\r\n@keyframes quizShine { 0% { transform: translateX(-150%) skewX(-18deg);} 100% { transform: translateX(250%) skewX(-18deg);} }\r\n\r\n/* HERO */\r\n.quiz-hero {\r\n  position: relative; overflow: hidden;\r\n  margin: 24px auto; max-width: 1280px;\r\n  padding: 56px 28px 40px;\r\n  border-radius: var(--radius-xl);\r\n  background:\r\n    linear-gradient(180deg, var(--surface), var(--surface)) padding-box,\r\n    linear-gradient(135deg, rgba(14,165,233,0.45), rgba(99,102,241,0.35), rgba(20,184,166,0.45)) border-box;\r\n  border: 1px solid transparent;\r\n  box-shadow: var(--shadow-md);\r\n}\r\n.quiz-hero__bg { position: absolute; inset: 0; pointer-events: none; overflow: hidden; }\r\n.quiz-hero__bg .blob {\r\n  position: absolute; border-radius: 50%; filter: blur(70px); opacity: 0.5;\r\n  animation: quizFloat 14s ease-in-out infinite;\r\n}\r\n.quiz-hero__bg .blob-1 { width: 280px; height: 280px; background: #38bdf8; top: -70px; left: -50px; }\r\n.quiz-hero__bg .blob-2 { width: 320px; height: 320px; background: #6366f1; bottom: -130px; right: -70px; animation-duration: 18s; }\r\n.quiz-hero__bg .blob-3 { width: 200px; height: 200px; background: #14b8a6; top: 40%; left: 55%; animation-duration: 22s; opacity: 0.35; }\r\n.quiz-hero__bg .dot-grid {\r\n  position: absolute; inset: 0;\r\n  background-image: radial-gradient(rgba(15,23,42,0.08) 1px, transparent 1px);\r\n  background-size: 18px 18px;\r\n  mask-image: radial-gradient(ellipse at center, black 30%, transparent 75%);\r\n  -webkit-mask-image: radial-gradient(ellipse at center, black 30%, transparent 75%);\r\n}\r\n[data-theme=\"black\"] .quiz-hero__bg .dot-grid {\r\n  background-image: radial-gradient(rgba(255,255,255,0.08) 1px, transparent 1px);\r\n}\r\n.quiz-hero__content { position: relative; z-index: 1; max-width: 1080px; margin: 0 auto; text-align: center; animation: quizFadeUp 0.7s var(--ease-spring) both; }\r\n.quiz-hero__brand { display: inline-flex; align-items: center; gap: 14px; margin-bottom: 14px; }\r\n.quiz-hero__logo {\r\n  width: 56px; height: 56px; -o-object-fit: contain; object-fit: contain;\r\n  border-radius: 14px; background: var(--surface); padding: 6px;\r\n  box-shadow: var(--shadow-sm); animation: quizFloat 6s ease-in-out infinite;\r\n}\r\n.quiz-hero__brand-meta { display: flex; flex-direction: column; align-items: flex-start; gap: 4px; }\r\n.quiz-chip {\r\n  background: var(--accent-soft) !important;\r\n  color: var(--accent) !important;\r\n  border: 1px solid var(--accent-ring) !important;\r\n  border-radius: 999px !important;\r\n  padding: 4px 12px !important;\r\n  font-weight: 700 !important; font-size: 11.5px !important;\r\n  letter-spacing: 0.08em; margin: 0 !important;\r\n}\r\n.quiz-hero__eyebrow { color: var(--text-muted); font-size: 13px; letter-spacing: 0.08em; text-transform: uppercase; }\r\n.quiz-hero__title {\r\n  font-size: clamp(28px, 4.4vw, 46px) !important;\r\n  line-height: 1.1 !important;\r\n  font-weight: 800 !important;\r\n  letter-spacing: -0.02em;\r\n  color: var(--text) !important;\r\n  margin: 6px 0 14px !important;\r\n}\r\n.grad-text {\r\n  background: linear-gradient(135deg, var(--accent) 0%, var(--accent-3) 50%, var(--accent-2) 100%);\r\n  -webkit-background-clip: text; background-clip: text;\r\n  -webkit-text-fill-color: transparent; color: transparent;\r\n}\r\n.quiz-hero__lead {\r\n  color: var(--text-muted) !important;\r\n  font-size: 16px !important; line-height: 1.7 !important;\r\n  max-width: 720px; margin: 0 auto 16px !important;\r\n}\r\n.quiz-hero__company {\r\n  display: flex; flex-wrap: wrap; align-items: center; justify-content: center;\r\n  gap: 14px; color: var(--text-muted); font-size: 13px; margin-top: 6px;\r\n}\r\n.quiz-hero__company .anticon { color: var(--accent); }\r\n.quiz-hero__tags { display: flex; justify-content: center; flex-wrap: wrap; gap: 8px; margin-top: 18px; }\r\n.quiz-hero__tags .ant-tag {\r\n  border-radius: 999px !important;\r\n  border: 1px solid var(--border) !important;\r\n  background: var(--surface) !important;\r\n  color: var(--text) !important;\r\n  padding: 6px 14px !important;\r\n  font-weight: 600 !important; font-size: 12.5px !important;\r\n  margin: 0 !important;\r\n}\r\n.quiz-hero__tags .ant-tag .anticon { color: var(--accent); margin-right: 6px; }\r\n\r\n/* Sections / cards */\r\n.quiz-section { max-width: 1280px; margin: 24px auto 0; padding: 0 28px; animation: quizFadeUp 0.7s var(--ease-spring) both; }\r\n.quiz-card {\r\n  background: var(--surface) !important;\r\n  border: 1px solid var(--border) !important;\r\n  border-radius: var(--radius-lg) !important;\r\n  box-shadow: var(--shadow-sm) !important;\r\n}\r\n.quiz-card .ant-card-body { padding: 22px 24px; }\r\n\r\n.quiz-stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(190px, 1fr)); gap: 14px; }\r\n.quiz-stat {\r\n  display: flex; align-items: center; gap: 12px;\r\n  padding: 14px 16px;\r\n  background: var(--surface-2);\r\n  border: 1px solid var(--border);\r\n  border-radius: var(--radius-md);\r\n  transition: all 0.25s var(--ease-smooth);\r\n}\r\n.quiz-stat:hover { transform: translateY(-2px); border-color: var(--accent-ring); box-shadow: var(--shadow-sm); }\r\n.quiz-stat__icon {\r\n  width: 44px; height: 44px; border-radius: 12px;\r\n  display: inline-flex; align-items: center; justify-content: center;\r\n  background: var(--accent-soft); color: var(--accent);\r\n  font-size: 18px; flex-shrink: 0;\r\n}\r\n.quiz-stat__label { display: block; color: var(--text-muted); font-size: 12px; }\r\n.quiz-stat__value { display: block; color: var(--text); font-size: 18px; font-weight: 700; line-height: 1.1; }\r\n.quiz-stat__sub { color: var(--text-subtle); font-size: 11.5px; }\r\n.quiz-footer__muted { color: var(--text-muted); font-weight: 500; }\r\n\r\n.quiz-divider { border-color: var(--border) !important; margin: 18px 0 !important; }\r\n\r\n/* Question Card */\r\n.quiz-question-card {\r\n  background: var(--surface) !important;\r\n  border: 1px solid var(--border) !important;\r\n  border-radius: var(--radius-lg) !important;\r\n  box-shadow: var(--shadow-sm) !important;\r\n  overflow: hidden;\r\n  position: relative;\r\n  animation: quizFadeUp 0.5s var(--ease-spring) both;\r\n}\r\n.quiz-question-card .ant-card-body { padding: 28px; }\r\n.quiz-question-meta { display: flex; align-items: center; flex-wrap: wrap; gap: 10px; margin-bottom: 12px; }\r\n.quiz-question-meta .ant-badge-count {\r\n  background: linear-gradient(135deg, var(--accent), var(--accent-3)) !important;\r\n  box-shadow: 0 4px 12px var(--accent-ring) !important;\r\n  border-radius: 999px !important;\r\n  font-weight: 700 !important;\r\n  padding: 0 12px !important;\r\n}\r\n.quiz-question-text {\r\n  color: var(--text) !important;\r\n  font-size: clamp(19px, 2.2vw, 24px) !important;\r\n  font-weight: 700 !important;\r\n  line-height: 1.45 !important;\r\n  margin: 4px 0 10px !important;\r\n  letter-spacing: -0.01em;\r\n}\r\n.quiz-question-text .anticon { color: var(--accent); margin-right: 8px; }\r\n.quiz-question-category { color: var(--text-muted) !important; font-size: 12.5px; }\r\n\r\n/* Image options */\r\n.image-options-grid { margin-top: 8px; }\r\n.image-option {\r\n  border: 2px solid var(--border);\r\n  border-radius: var(--radius-md);\r\n  background: var(--surface);\r\n  overflow: hidden;\r\n  cursor: pointer;\r\n  transition: all 0.3s var(--ease-spring);\r\n  position: relative;\r\n  height: 100%;\r\n}\r\n.image-option:hover {\r\n  transform: translateY(-4px);\r\n  border-color: var(--accent-ring);\r\n  box-shadow: var(--shadow-md);\r\n}\r\n.image-option.selected {\r\n  border-color: var(--accent);\r\n  box-shadow: 0 14px 30px var(--accent-ring);\r\n  transform: translateY(-4px);\r\n}\r\n.image-option .image-container { background: var(--surface-2); }\r\n.image-option .ant-image { width: 100% !important; display: block; }\r\n.image-option .option-label {\r\n  display: flex; align-items: center; justify-content: space-between;\r\n  padding: 10px 14px;\r\n  background: var(--surface);\r\n  border-top: 1px solid var(--border);\r\n}\r\n.image-option .option-label .label-text { color: var(--text); font-weight: 700; }\r\n.image-option .selection-indicator {\r\n  width: 24px; height: 24px;\r\n  border-radius: 50%;\r\n  display: inline-flex; align-items: center; justify-content: center;\r\n  color: var(--accent);\r\n}\r\n.image-option .radio-placeholder {\r\n  width: 18px; height: 18px; border-radius: 50%;\r\n  border: 2px solid var(--border-strong);\r\n  background: var(--surface);\r\n}\r\n\r\n/* Buttons */\r\n.btn-primary-grad {\r\n  background: linear-gradient(135deg, var(--accent), var(--accent-3)) !important;\r\n  border: none !important;\r\n  height: 46px !important;\r\n  padding: 0 22px !important;\r\n  border-radius: 12px !important;\r\n  font-weight: 700 !important; color: #fff !important;\r\n  box-shadow: 0 10px 24px var(--accent-ring) !important;\r\n  position: relative; overflow: hidden;\r\n}\r\n.btn-primary-grad::after {\r\n  content: \"\"; position: absolute; top: 0; left: 0; width: 60%; height: 100%;\r\n  background: linear-gradient(90deg, transparent, rgba(255,255,255,0.35), transparent);\r\n  animation: quizShine 2.8s ease-in-out infinite;\r\n}\r\n.btn-primary-grad:hover { transform: translateY(-1px); }\r\n.btn-primary-grad[disabled],\r\n.btn-primary-grad[disabled]:hover {\r\n  background: var(--surface-2) !important;\r\n  color: var(--text-subtle) !important;\r\n  box-shadow: none !important;\r\n}\r\n.btn-primary-grad[disabled]::after { display: none; }\r\n.btn-ghost {\r\n  height: 46px !important;\r\n  padding: 0 20px !important;\r\n  border-radius: 12px !important;\r\n  font-weight: 600 !important;\r\n  background: var(--surface) !important;\r\n  border: 1px solid var(--border-strong) !important;\r\n  color: var(--text) !important;\r\n}\r\n.btn-ghost:hover { border-color: var(--accent) !important; color: var(--accent) !important; }\r\n.btn-ghost[disabled] { opacity: 0.55; cursor: not-allowed; }\r\n\r\n.quiz-navigation {\r\n  display: flex; justify-content: space-between; align-items: center;\r\n  gap: 14px; margin: 14px 0; flex-wrap: wrap;\r\n  padding: 14px 18px;\r\n  background: var(--surface-2);\r\n  border: 1px solid var(--border);\r\n  border-radius: var(--radius-md);\r\n}\r\n\r\n/* Submit card */\r\n.quiz-submit-card {\r\n  background: var(--surface) !important;\r\n  border: 1px dashed var(--accent-ring) !important;\r\n  border-radius: var(--radius-lg) !important;\r\n  box-shadow: var(--shadow-sm) !important;\r\n  text-align: center; padding: 8px;\r\n}\r\n.quiz-submit-card .ant-card-body { padding: 28px; }\r\n\r\n/* Loading */\r\n.quiz-loading {\r\n  min-height: 100vh; display: flex; align-items: center; justify-content: center;\r\n  background: var(--bg);\r\n}\r\n\r\n/* Completion */\r\n.quiz-completion-card {\r\n  background: var(--surface) !important;\r\n  border: 1px solid var(--border) !important;\r\n  border-radius: var(--radius-xl) !important;\r\n  box-shadow: var(--shadow-md) !important;\r\n}\r\n\r\n/* Responsive */\r\n@media (max-width: 768px) {\r\n  .quiz-hero { padding: 40px 18px 28px; margin: 16px; }\r\n  .quiz-section { padding: 0 16px; }\r\n  .quiz-question-card .ant-card-body { padding: 20px; }\r\n  .quiz-hero__brand { flex-direction: column; gap: 10px; }\r\n  .quiz-hero__brand-meta { align-items: center; }\r\n}\r\n@media (max-width: 480px) {\r\n  .quiz-hero__title { font-size: 26px !important; }\r\n  .quiz-hero__lead { font-size: 14.5px !important; }\r\n}\r\n\r\n/* Reduced motion */\r\n@media (prefers-reduced-motion: reduce) {\r\n  .quiz-page, .quiz-hero__content, .quiz-section,\r\n  .quiz-question-card, .image-option,\r\n  .quiz-hero__logo, .quiz-hero__bg .blob,\r\n  .btn-primary-grad::after { animation: none !important; transition: none !important; }\r\n}\r\n/* ==============================================\r\n   Time Expired Modal / Resume Modal / Net Banner\r\n   ============================================== */\r\n\r\n@keyframes quizPulseRing {\r\n  0% { box-shadow: 0 0 0 0 rgba(79, 70, 229, 0.55); }\r\n  70% { box-shadow: 0 0 0 22px rgba(79, 70, 229, 0); }\r\n  100% { box-shadow: 0 0 0 0 rgba(79, 70, 229, 0); }\r\n}\r\n@keyframes quizClockSpin {\r\n  0% { transform: rotate(0deg) scale(1); }\r\n  50% { transform: rotate(8deg) scale(1.06); }\r\n  100% { transform: rotate(0deg) scale(1); }\r\n}\r\n@keyframes quizModalPop {\r\n  from { opacity: 0; transform: translateY(14px) scale(0.96); }\r\n  to   { opacity: 1; transform: translateY(0) scale(1); }\r\n}\r\n@keyframes quizCountdownPulse {\r\n  0%, 100% { transform: scale(1); }\r\n  50% { transform: scale(1.08); }\r\n}\r\n@keyframes quizBannerSlide {\r\n  from { transform: translateY(-100%); opacity: 0; }\r\n  to { transform: translateY(0); opacity: 1; }\r\n}\r\n\r\n.quiz-page.is-locked { pointer-events: none; -webkit-user-select: none; -moz-user-select: none; user-select: none; }\r\n.quiz-page.is-locked .ant-modal-root,\r\n.quiz-page.is-locked .ant-notification { pointer-events: auto; }\r\n\r\n.image-option.is-disabled { opacity: 0.55; pointer-events: none; filter: grayscale(0.2); }\r\n\r\n/* Offline / Online banner */\r\n.net-banner {\r\n  position: sticky; top: 0; z-index: 950;\r\n  display: flex; align-items: center; gap: 10px;\r\n  padding: 12px 18px;\r\n  font-weight: 600; font-size: 13.5px;\r\n  animation: quizBannerSlide 0.35s var(--ease-spring) both;\r\n}\r\n.net-banner .anticon { font-size: 18px; }\r\n.net-banner--offline {\r\n  background: linear-gradient(90deg, #f59e0b, #ef4444);\r\n  color: #fff;\r\n  box-shadow: 0 8px 24px rgba(239, 68, 68, 0.25);\r\n}\r\n\r\n/* Resume Modal */\r\n.resume-modal .ant-modal-content {\r\n  background: var(--surface) !important;\r\n  border: 1px solid var(--border) !important;\r\n  border-radius: var(--radius-xl) !important;\r\n  box-shadow: var(--shadow-lg) !important;\r\n  padding: 0 !important;\r\n  overflow: hidden;\r\n  animation: quizModalPop 0.35s var(--ease-spring) both;\r\n}\r\n.resume-modal .ant-modal-body { padding: 0 !important; }\r\n.resume-modal__body {\r\n  padding: 32px 28px;\r\n  text-align: center;\r\n  background:\r\n    radial-gradient(700px 240px at 50% -10%, var(--accent-soft), transparent 70%),\r\n    var(--surface);\r\n}\r\n.resume-modal__icon {\r\n  width: 72px; height: 72px; margin: 0 auto 16px;\r\n  border-radius: 50%;\r\n  display: inline-flex; align-items: center; justify-content: center;\r\n  background: linear-gradient(135deg, var(--accent), var(--accent-3));\r\n  color: #fff; font-size: 30px;\r\n  box-shadow: 0 14px 30px var(--accent-ring);\r\n}\r\n.resume-modal__title {\r\n  color: var(--text); margin: 0 0 10px;\r\n  font-size: 20px; font-weight: 800; letter-spacing: -0.01em;\r\n}\r\n.resume-modal__text {\r\n  color: var(--text-muted); font-size: 14px; line-height: 1.6;\r\n  margin: 0 auto 22px; max-width: 360px;\r\n}\r\n.resume-modal__actions {\r\n  display: flex; gap: 10px; justify-content: center; flex-wrap: wrap;\r\n}\r\n\r\n/* Time Expired Modal */\r\n.expired-modal .ant-modal-content {\r\n  background: linear-gradient(160deg, #121620 0%, #0a0c12 100%) !important;\r\n  border: 1px solid #242a36 !important;\r\n  border-radius: var(--radius-xl) !important;\r\n  box-shadow: 0 30px 80px rgba(0,0,0,0.55) !important;\r\n  padding: 0 !important;\r\n  overflow: hidden;\r\n  -webkit-backdrop-filter: blur(18px);\r\n          backdrop-filter: blur(18px);\r\n  animation: quizModalPop 0.35s var(--ease-spring) both;\r\n}\r\n.expired-modal .ant-modal-mask {\r\n  background: rgba(2, 6, 23, 0.7) !important;\r\n  -webkit-backdrop-filter: blur(8px);\r\n          backdrop-filter: blur(8px);\r\n}\r\n.expired-modal .ant-modal-body { padding: 0 !important; }\r\n.expired-modal__body {\r\n  position: relative;\r\n  padding: 36px 28px 30px;\r\n  text-align: center;\r\n  color: #e7ecf3;\r\n  background:\r\n    radial-gradient(600px 260px at 50% -10%, rgba(79, 70, 229, 0.30), transparent 70%),\r\n    radial-gradient(500px 220px at 50% 120%, rgba(124, 58, 237, 0.25), transparent 70%);\r\n}\r\n.expired-modal__clock {\r\n  width: 96px; height: 96px; margin: 4px auto 14px;\r\n  border-radius: 50%;\r\n  display: inline-flex; align-items: center; justify-content: center;\r\n  font-size: 48px; color: #fff;\r\n  background: linear-gradient(135deg, #4f46e5, #7c3aed, #0ea5e9);\r\n  box-shadow: 0 18px 40px rgba(79, 70, 229, 0.45);\r\n  animation: quizClockSpin 2.4s ease-in-out infinite, quizPulseRing 2s ease-out infinite;\r\n}\r\n.expired-modal__title {\r\n  font-size: 22px; font-weight: 800; letter-spacing: 0.02em;\r\n  margin: 4px 0 14px;\r\n}\r\n.expired-modal__title .grad-text {\r\n  background: linear-gradient(135deg, #818cf8 0%, #c084fc 50%, #38bdf8 100%);\r\n  -webkit-background-clip: text; background-clip: text;\r\n  -webkit-text-fill-color: transparent;\r\n}\r\n.expired-modal__text {\r\n  color: #cbd5e1; font-size: 14.5px; line-height: 1.65;\r\n  margin: 0 auto 10px; max-width: 420px;\r\n}\r\n.expired-modal__text--muted { color: #9aa4b2; font-size: 13.5px; }\r\n.expired-modal__countdown {\r\n  display: inline-flex; align-items: center; gap: 12px;\r\n  margin: 18px auto 14px;\r\n  padding: 10px 18px;\r\n  background: rgba(255,255,255,0.04);\r\n  border: 1px solid rgba(255,255,255,0.08);\r\n  border-radius: 999px;\r\n  color: #e7ecf3; font-weight: 600; font-size: 14px;\r\n}\r\n.expired-modal__badge {\r\n  display: inline-flex; align-items: center; justify-content: center;\r\n  min-width: 36px; height: 36px; padding: 0 10px;\r\n  border-radius: 50%;\r\n  background: linear-gradient(135deg, #ef4444, #f59e0b);\r\n  color: #fff; font-weight: 800; font-size: 16px;\r\n  box-shadow: 0 6px 18px rgba(239, 68, 68, 0.45);\r\n  animation: quizCountdownPulse 1s ease-in-out infinite;\r\n}\r\n.expired-modal__progress {\r\n  height: 8px; width: 100%; max-width: 420px; margin: 8px auto 14px;\r\n  border-radius: 999px; overflow: hidden;\r\n  background: rgba(255,255,255,0.06);\r\n  border: 1px solid rgba(255,255,255,0.06);\r\n}\r\n.expired-modal__progress-bar {\r\n  height: 100%;\r\n  background: linear-gradient(90deg, #4f46e5, #7c3aed, #0ea5e9);\r\n  transition: width 0.9s linear;\r\n  box-shadow: 0 0 16px rgba(124, 58, 237, 0.55);\r\n}\r\n.expired-modal__logout {\r\n  display: inline-flex; align-items: center; gap: 8px;\r\n  color: #9aa4b2; font-size: 13px; font-weight: 600;\r\n}\r\n.expired-modal__logout .anticon { color: #c084fc; }\r\n\r\n/* Mobile responsive */\r\n@media (max-width: 540px) {\r\n  .resume-modal__body { padding: 26px 18px; }\r\n  .resume-modal__title { font-size: 18px; }\r\n  .resume-modal__actions .ant-btn { width: 100%; }\r\n  .expired-modal__body { padding: 28px 18px 24px; }\r\n  .expired-modal__clock { width: 80px; height: 80px; font-size: 40px; }\r\n  .expired-modal__title { font-size: 19px; }\r\n  .expired-modal__text { font-size: 13.5px; }\r\n  .net-banner { font-size: 12.5px; padding: 10px 14px; }\r\n}\r\n\r\n@media (prefers-reduced-motion: reduce) {\r\n  .expired-modal__clock,\r\n  .expired-modal__badge,\r\n  .resume-modal .ant-modal-content,\r\n  .expired-modal .ant-modal-content,\r\n  .net-banner { animation: none !important; }\r\n}\r\n\r\n/* ============================================================\r\n   THEMED ANT DESIGN MODAL OVERRIDES (auto-injected)\r\n   Drives every Modal / Modal.confirm / .info / .success / .error\r\n   to respect the app theme via [data-theme=\"black\"|\"white\"].\r\n   ============================================================ */\r\n\r\n/* ----- DARK THEME ----- */\r\n[data-theme=\"black\"] .ant-modal-content {\r\n    background: #141414 !important;\r\n    border: 1px solid #303746 !important;\r\n    border-radius: 12px !important;\r\n    box-shadow: 0 24px 60px rgba(0, 0, 0, 0.6) !important;\r\n}\r\n[data-theme=\"black\"] .ant-modal-header {\r\n    background: #141414 !important;\r\n    border-bottom: 1px solid #303746 !important;\r\n}\r\n[data-theme=\"black\"] .ant-modal-title {\r\n    color: #ffffff !important;\r\n}\r\n[data-theme=\"black\"] .ant-modal-body {\r\n    background: #1a1f2b !important;\r\n    color: #e7ecf3 !important;\r\n}\r\n[data-theme=\"black\"] .ant-modal-footer {\r\n    background: #141414 !important;\r\n    border-top: 1px solid #303746 !important;\r\n}\r\n[data-theme=\"black\"] .ant-modal-close,\r\n[data-theme=\"black\"] .ant-modal-close-x {\r\n    color: #ffffff !important;\r\n}\r\n\r\n/* Confirm/info/success/error icon-row variants */\r\n[data-theme=\"black\"] .ant-modal-confirm .ant-modal-content,\r\n[data-theme=\"black\"] .ant-modal-confirm-body-wrapper {\r\n    background: #141414 !important;\r\n}\r\n[data-theme=\"black\"] .ant-modal-confirm-title {\r\n    color: #ffffff !important;\r\n}\r\n[data-theme=\"black\"] .ant-modal-confirm-content,\r\n[data-theme=\"black\"] .ant-modal-confirm-content p,\r\n[data-theme=\"black\"] .ant-modal-confirm-content li,\r\n[data-theme=\"black\"] .ant-modal-confirm-content span {\r\n    color: #e7ecf3 !important;\r\n}\r\n\r\n/* Typography/Statistic/Alert/Result auto-color */\r\n[data-theme=\"black\"] .ant-modal-body .ant-typography,\r\n[data-theme=\"black\"] .ant-modal-body .ant-typography h1,\r\n[data-theme=\"black\"] .ant-modal-body .ant-typography h2,\r\n[data-theme=\"black\"] .ant-modal-body .ant-typography h3,\r\n[data-theme=\"black\"] .ant-modal-body .ant-typography h4,\r\n[data-theme=\"black\"] .ant-modal-body .ant-typography h5,\r\n[data-theme=\"black\"] .ant-modal-body p,\r\n[data-theme=\"black\"] .ant-modal-body li,\r\n[data-theme=\"black\"] .ant-modal-body label {\r\n    color: #e7ecf3 !important;\r\n}\r\n[data-theme=\"black\"] .ant-modal-body .ant-typography-secondary,\r\n[data-theme=\"black\"] .ant-modal-body .ant-typography.ant-typography-secondary {\r\n    color: #9aa4b2 !important;\r\n}\r\n[data-theme=\"black\"] .ant-modal-body .ant-statistic-title {\r\n    color: #9aa4b2 !important;\r\n}\r\n[data-theme=\"black\"] .ant-modal-body .ant-statistic-content,\r\n[data-theme=\"black\"] .ant-modal-body .ant-statistic-content-value,\r\n[data-theme=\"black\"] .ant-modal-body .ant-statistic-content-suffix,\r\n[data-theme=\"black\"] .ant-modal-body .ant-statistic-content-prefix {\r\n    color: #ffffff !important;\r\n}\r\n[data-theme=\"black\"] .ant-modal-body .ant-alert {\r\n    background: #1f2937 !important;\r\n    border-color: #303746 !important;\r\n    color: #e7ecf3 !important;\r\n}\r\n[data-theme=\"black\"] .ant-modal-body .ant-alert-message,\r\n[data-theme=\"black\"] .ant-modal-body .ant-alert-description {\r\n    color: #e7ecf3 !important;\r\n}\r\n[data-theme=\"black\"] .ant-modal-body .ant-result-title {\r\n    color: #ffffff !important;\r\n}\r\n[data-theme=\"black\"] .ant-modal-body .ant-result-subtitle {\r\n    color: #9aa4b2 !important;\r\n}\r\n\r\n/* ----- LIGHT THEME ----- */\r\n[data-theme=\"white\"] .ant-modal-content,\r\n:root:not([data-theme=\"black\"]) .ant-modal-content {\r\n    background: #ffffff !important;\r\n    color: #000000 !important;\r\n    border: 1px solid #e2e8f0 !important;\r\n    border-radius: 12px !important;\r\n}\r\n[data-theme=\"white\"] .ant-modal-header,\r\n:root:not([data-theme=\"black\"]) .ant-modal-header {\r\n    background: #ffffff !important;\r\n    border-bottom: 1px solid #e2e8f0 !important;\r\n}\r\n[data-theme=\"white\"] .ant-modal-title,\r\n:root:not([data-theme=\"black\"]) .ant-modal-title {\r\n    color: #0b1220 !important;\r\n}\r\n[data-theme=\"white\"] .ant-modal-body,\r\n:root:not([data-theme=\"black\"]) .ant-modal-body {\r\n    background: #f8fafc !important;\r\n    color: #000000 !important;\r\n}\r\n[data-theme=\"white\"] .ant-modal-footer,\r\n:root:not([data-theme=\"black\"]) .ant-modal-footer {\r\n    background: #ffffff !important;\r\n    border-top: 1px solid #e2e8f0 !important;\r\n}\r\n[data-theme=\"white\"] .ant-modal-body .ant-typography-secondary {\r\n    color: #5b6677 !important;\r\n}\r\n\r\n/* Helper className we attach from JS */\r\n.themed-modal .ant-modal-content {\r\n    border-radius: 12px !important;\r\n    overflow: hidden;\r\n}", ""]);
