___CSS_LOADER_EXPORT___.push([module.id, "/* ==========================================================================\r\n   InstallPwaPage.css\r\n   OCC Alumni — Public \"Install PWA\" guide page\r\n   Imports PublicHomePage.css for shared tokens (--ph-accent, .ph-btn,\r\n   .ph-card, .grad, .ph-header, .ph-footer, etc); everything here is\r\n   additive, namespaced with a \"pwa-\" prefix so nothing collides with\r\n   the rest of the public site.\r\n   ========================================================================== */\r\n\r\n.pwa-page {\r\n  min-height: 100vh;\r\n}\r\n\r\n/* ============ BREADCRUMB: mobile-only ============\r\n   This is the small \"Home / INSTALL PWA\" trail above the page title —\r\n   NOT the header. On desktop/laptop it just repeats what's already in\r\n   the header nav, so it's hidden there and only shown on phones. The\r\n   header itself is never touched by this rule. */\r\n.pwa-page .pwa-breadcrumb {\r\n  display: none;\r\n}\r\n\r\n@media (max-width: 767px) {\r\n  .pwa-page .pwa-breadcrumb {\r\n    display: flex;\r\n  }\r\n}\r\n\r\n/* ============ BREADCRUMB + HERO ============ */\r\n.pwa-hero {\r\n  max-width: 900px;\r\n  margin: 0 auto;\r\n  padding: 40px 32px 8px;\r\n}\r\n\r\n.pwa-breadcrumb {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n  font-size: 12.5px;\r\n  font-weight: 700;\r\n  letter-spacing: 0.04em;\r\n  text-transform: uppercase;\r\n  opacity: 0.55;\r\n  margin-bottom: 18px;\r\n}\r\n\r\n.pwa-breadcrumb button {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 6px;\r\n  background: none;\r\n  border: none;\r\n  padding: 0;\r\n  font: inherit;\r\n  color: inherit;\r\n  cursor: pointer;\r\n  opacity: 0.85;\r\n}\r\n\r\n.pwa-breadcrumb button:hover {\r\n  color: var(--ph-accent);\r\n  opacity: 1;\r\n}\r\n\r\n.pwa-breadcrumb-current {\r\n  color: var(--ph-accent);\r\n}\r\n\r\n.pwa-hero-title {\r\n  font-size: 40px !important;\r\n  font-weight: 900 !important;\r\n  margin: 0 0 12px !important;\r\n  color: inherit !important;\r\n}\r\n\r\n.pwa-hero-lead {\r\n  font-size: 15.5px !important;\r\n  opacity: 0.72;\r\n  color: inherit !important;\r\n  max-width: 640px;\r\n  margin: 0 !important;\r\n}\r\n\r\n/* ============ SECTION / CARD SHELL ============ */\r\n.pwa-section {\r\n  padding-top: 8px;\r\n  padding-bottom: 20px;\r\n}\r\n\r\n.pwa-card {\r\n  max-width: 900px;\r\n  margin: 0 auto;\r\n  padding: 28px 30px;\r\n  border-radius: var(--ph-radius-md, 18px);\r\n}\r\n\r\n.ph-page.light .pwa-card {\r\n  background: #ffffff;\r\n  border: 1px solid #edf0f5;\r\n  box-shadow: 0 10px 30px rgba(2, 6, 23, 0.05);\r\n}\r\n\r\n.ph-page.dark .pwa-card {\r\n  background: rgba(18, 22, 32, 0.75);\r\n  border: 1px solid #242a36;\r\n  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.3);\r\n}\r\n\r\n.pwa-card-heading {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 10px;\r\n  font-size: 20px;\r\n  font-weight: 800;\r\n  margin-bottom: 4px;\r\n  color: inherit;\r\n}\r\n\r\n.pwa-card-heading .anticon {\r\n  color: var(--ph-accent);\r\n}\r\n\r\n.pwa-card-sub {\r\n  display: block;\r\n  font-size: 13px;\r\n  opacity: 0.55;\r\n  margin-bottom: 14px;\r\n}\r\n\r\n.pwa-p {\r\n  font-size: 14.5px !important;\r\n  line-height: 1.7 !important;\r\n  opacity: 0.82;\r\n  color: inherit !important;\r\n  margin: 0 0 12px !important;\r\n}\r\n\r\n.pwa-p:last-child {\r\n  margin-bottom: 0 !important;\r\n}\r\n\r\n.pwa-p a {\r\n  color: var(--ph-accent);\r\n  font-weight: 600;\r\n}\r\n\r\n.pwa-link-chip {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n  margin-top: 6px;\r\n  padding: 8px 16px;\r\n  border-radius: 999px;\r\n  font-size: 13.5px;\r\n  font-weight: 700;\r\n  color: var(--ph-accent);\r\n  text-decoration: none;\r\n}\r\n\r\n.ph-page.light .pwa-link-chip {\r\n  background: #f5f7fb;\r\n  border: 1px solid #e6eaf1;\r\n}\r\n\r\n.ph-page.dark .pwa-link-chip {\r\n  background: rgba(255, 255, 255, 0.05);\r\n  border: 1px solid #242a36;\r\n}\r\n\r\n.pwa-link-chip:hover {\r\n  transform: translateY(-1px);\r\n}\r\n\r\n/* ============ OVERVIEW ============ */\r\n.pwa-overview-body {\r\n  display: grid;\r\n  grid-template-columns: 260px 1fr;\r\n  gap: 32px;\r\n  align-items: center;\r\n  margin-top: 18px;\r\n}\r\n\r\n.pwa-overview-mockup {\r\n  display: flex;\r\n  justify-content: center;\r\n}\r\n\r\n.pwa-overview-mockup img {\r\n  width: 100%;\r\n  max-width: 240px;\r\n  height: auto;\r\n  display: block;\r\n  border-radius: 22px;\r\n}\r\n\r\n/* ============ iOS STEPS ============ */\r\n.pwa-steps {\r\n  display: grid;\r\n  grid-template-columns: repeat(3, 1fr);\r\n  gap: 24px;\r\n  align-items: start;\r\n  margin-top: 18px;\r\n}\r\n\r\n.pwa-step-card {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 14px;\r\n}\r\n\r\n.pwa-step-card-shot {\r\n  border-radius: 16px;\r\n  overflow: hidden;\r\n  line-height: 0;\r\n  max-width: 190px;\r\n  margin: 0 auto;\r\n}\r\n\r\n.ph-page.light .pwa-step-card-shot {\r\n  border: 1px solid #e6eaf1;\r\n  box-shadow: 0 8px 20px rgba(2, 6, 23, 0.08);\r\n}\r\n\r\n.ph-page.dark .pwa-step-card-shot {\r\n  border: 1px solid #242a36;\r\n  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.35);\r\n}\r\n\r\n.pwa-step-card-shot img {\r\n  width: 100%;\r\n  height: auto;\r\n  display: block;\r\n}\r\n\r\n.pwa-step {\r\n  display: flex;\r\n  align-items: flex-start;\r\n  gap: 12px;\r\n}\r\n\r\n.pwa-step-num {\r\n  flex-shrink: 0;\r\n  width: 34px;\r\n  height: 34px;\r\n  border-radius: 50%;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  font-size: 15px;\r\n  color: #ffffff;\r\n  background: linear-gradient(135deg, var(--ph-accent), var(--ph-accent-2));\r\n}\r\n\r\n.pwa-step strong {\r\n  display: block;\r\n  font-size: 14px;\r\n  margin-bottom: 2px;\r\n}\r\n\r\n.pwa-step p {\r\n  margin: 0;\r\n  font-size: 13px;\r\n  opacity: 0.65;\r\n  line-height: 1.5;\r\n}\r\n\r\n/* ==========================================================================\r\n   RESPONSIVE\r\n   ========================================================================== */\r\n@media (max-width: 767px) {\r\n  .pwa-hero { padding: 28px 20px 4px; }\r\n  .pwa-hero-title { font-size: 27px !important; }\r\n  .pwa-hero-lead { font-size: 14px !important; }\r\n\r\n  .pwa-card { padding: 22px 20px; }\r\n\r\n  .pwa-overview-body {\r\n    grid-template-columns: 1fr;\r\n    gap: 20px;\r\n    text-align: center;\r\n  }\r\n\r\n  .pwa-steps {\r\n    grid-template-columns: 1fr;\r\n    gap: 20px;\r\n  }\r\n\r\n  .pwa-step-card-shot {\r\n    max-width: 280px;\r\n    margin: 0 auto;\r\n  }\r\n}\r\n\r\n@media (max-width: 575px) {\r\n  .pwa-hero-title { font-size: 23px !important; }\r\n  .pwa-card-heading { font-size: 18px; }\r\n}", ""]);
