___CSS_LOADER_EXPORT___.push([module.id, "/* ==========================================================================\r\n   PublicContactPage.css\r\n   OCC Alumni — Public \"Contact Us\" page\r\n   Imports PublicHomePage.css for shared tokens (--ph-accent, .ph-btn,\r\n   .ph-card, .grad, .ph-header, .ph-footer, etc); everything here is\r\n   additive, namespaced with a \"pcon-\" prefix so nothing collides with\r\n   the rest of the public site.\r\n   ========================================================================== */\r\n\r\n.pcon-page {\r\n  min-height: 100vh;\r\n}\r\n\r\n/* ============ BREADCRUMB: mobile-only ============\r\n   This is the small \"Home / CONTACT US\" trail above the page title —\r\n   NOT the header. On desktop/laptop it just repeats what's already in\r\n   the header nav, so it's hidden there and only shown on phones. The\r\n   header itself is never touched by this rule. */\r\n.pcon-page .pcon-breadcrumb {\r\n  display: none;\r\n}\r\n\r\n@media (max-width: 767px) {\r\n  .pcon-page .pcon-breadcrumb {\r\n    display: flex;\r\n  }\r\n}\r\n\r\n/* ============ BREADCRUMB + HERO ============ */\r\n.pcon-hero {\r\n  max-width: 900px;\r\n  margin: 0 auto;\r\n  padding: 48px 32px 8px;\r\n  text-align: center;\r\n}\r\n\r\n.pcon-breadcrumb {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  gap: 8px;\r\n  font-size: 12.5px;\r\n  font-weight: 700;\r\n  letter-spacing: 0.04em;\r\n  text-transform: uppercase;\r\n  opacity: 0.55;\r\n  margin-bottom: 18px;\r\n}\r\n\r\n.pcon-breadcrumb button {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 6px;\r\n  background: none;\r\n  border: none;\r\n  padding: 0;\r\n  font: inherit;\r\n  color: inherit;\r\n  cursor: pointer;\r\n  opacity: 0.85;\r\n}\r\n\r\n.pcon-breadcrumb button:hover {\r\n  color: var(--ph-accent);\r\n  opacity: 1;\r\n}\r\n\r\n.pcon-breadcrumb-current {\r\n  color: var(--ph-accent);\r\n}\r\n\r\n.pcon-hero-title {\r\n  font-size: 40px !important;\r\n  font-weight: 900 !important;\r\n  margin: 0 0 12px !important;\r\n  color: inherit !important;\r\n}\r\n\r\n.pcon-hero-lead {\r\n  font-size: 15.5px !important;\r\n  opacity: 0.72;\r\n  color: inherit !important;\r\n  max-width: 620px;\r\n  margin: 0 auto !important;\r\n}\r\n\r\n/* ============ SECTION / GRID ============ */\r\n.pcon-section {\r\n  padding-top: 12px;\r\n  padding-bottom: 24px;\r\n}\r\n\r\n.pcon-grid {\r\n  max-width: 1080px;\r\n  margin: 0 auto;\r\n  padding: 0 24px;\r\n  display: grid;\r\n  grid-template-columns: 0.85fr 1.15fr;\r\n  gap: 26px;\r\n  align-items: start;\r\n}\r\n\r\n/* ============ SHARED CARD SHELL ============ */\r\n.pcon-card {\r\n  border-radius: var(--ph-radius-md, 18px);\r\n  padding: 28px 30px;\r\n}\r\n\r\n.ph-page.light .pcon-card {\r\n  background: #ffffff;\r\n  border: 1px solid #edf0f5;\r\n  box-shadow: 0 10px 30px rgba(2, 6, 23, 0.05);\r\n}\r\n\r\n.ph-page.dark .pcon-card {\r\n  background: rgba(18, 22, 32, 0.75);\r\n  border: 1px solid #242a36;\r\n  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.3);\r\n}\r\n\r\n.pcon-card-heading {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 10px;\r\n  font-size: 19px;\r\n  font-weight: 800;\r\n  margin-bottom: 4px;\r\n  color: inherit;\r\n}\r\n\r\n.pcon-card-heading .anticon {\r\n  color: var(--ph-accent);\r\n}\r\n\r\n.pcon-card-sub {\r\n  display: block;\r\n  font-size: 13px;\r\n  opacity: 0.55;\r\n  margin-bottom: 18px;\r\n}\r\n\r\n.pcon-required {\r\n  color: #ef4444;\r\n  font-weight: 800;\r\n}\r\n\r\n.pcon-p {\r\n  font-size: 13.5px !important;\r\n  line-height: 1.65 !important;\r\n  opacity: 0.75;\r\n  color: inherit !important;\r\n  margin: 0 0 18px !important;\r\n}\r\n\r\n.pcon-p a {\r\n  color: var(--ph-accent);\r\n  font-weight: 600;\r\n}\r\n\r\n/* ============ LEFT: CONTACT INFO ============ */\r\n.pcon-info-list {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 18px;\r\n  margin-bottom: 22px;\r\n}\r\n\r\n.pcon-info-item {\r\n  display: flex;\r\n  align-items: flex-start;\r\n  gap: 14px;\r\n}\r\n\r\n.pcon-info-icon {\r\n  flex-shrink: 0;\r\n  width: 42px;\r\n  height: 42px;\r\n  border-radius: 12px;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  font-size: 17px;\r\n  color: var(--ph-accent);\r\n  background: rgba(79, 70, 229, 0.1);\r\n}\r\n\r\n.pcon-info-item strong {\r\n  display: block;\r\n  font-size: 13.5px;\r\n  margin-bottom: 3px;\r\n}\r\n\r\n.pcon-info-item p {\r\n  margin: 0;\r\n  font-size: 13.5px;\r\n  opacity: 0.7;\r\n  line-height: 1.55;\r\n}\r\n\r\n.pcon-info-item a {\r\n  color: inherit;\r\n  text-decoration: none;\r\n}\r\n\r\n.pcon-info-item a:hover {\r\n  color: var(--ph-accent);\r\n}\r\n\r\n.pcon-social {\r\n  display: flex;\r\n  gap: 10px;\r\n  padding-top: 18px;\r\n}\r\n\r\n.ph-page.light .pcon-social {\r\n  border-top: 1px dashed #e6eaf1;\r\n}\r\n\r\n.ph-page.dark .pcon-social {\r\n  border-top: 1px dashed #242a36;\r\n}\r\n\r\n.pcon-social {\r\n  padding-top: 18px;\r\n}\r\n\r\n.pcon-social a {\r\n  width: 38px;\r\n  height: 38px;\r\n  border-radius: 50%;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  color: var(--ph-accent);\r\n  font-size: 15px;\r\n  text-decoration: none;\r\n  transition: transform 0.2s ease, background 0.2s ease, color 0.2s ease;\r\n}\r\n\r\n.ph-page.light .pcon-social a { background: #f5f7fb; border: 1px solid #e6eaf1; }\r\n.ph-page.dark .pcon-social a { background: rgba(255, 255, 255, 0.05); border: 1px solid #242a36; }\r\n\r\n.pcon-social a:hover {\r\n  background: linear-gradient(135deg, var(--ph-accent), var(--ph-accent-2));\r\n  color: #fff;\r\n  transform: translateY(-2px);\r\n}\r\n\r\n/* ============ RIGHT: FORM ============ */\r\n.pcon-form {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 18px;\r\n}\r\n\r\n/* Honeypot — off-screen, not just display:none (some bots skip\r\n   display:none fields), never reachable by Tab or a screen reader. */\r\n.pcon-honeypot {\r\n  position: absolute;\r\n  width: 1px;\r\n  height: 1px;\r\n  overflow: hidden;\r\n  clip: rect(0 0 0 0);\r\n  clip-path: inset(50%);\r\n  white-space: nowrap;\r\n}\r\n\r\n.pcon-error {\r\n  font-size: 13px;\r\n  font-weight: 600;\r\n  padding: 11px 14px;\r\n  border-radius: var(--ph-radius-sm, 12px);\r\n  background: rgba(239, 68, 68, 0.1);\r\n  color: #ef4444;\r\n}\r\n\r\n.pcon-field {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 7px;\r\n}\r\n\r\n.pcon-label {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 7px;\r\n  font-size: 13px;\r\n  font-weight: 700;\r\n  opacity: 0.8;\r\n}\r\n\r\n.pcon-label .anticon {\r\n  color: var(--ph-accent);\r\n}\r\n\r\n.pcon-field input,\r\n.pcon-field textarea {\r\n  width: 100%;\r\n  border-radius: var(--ph-radius-sm, 12px);\r\n  padding: 11px 14px;\r\n  font-size: 14px;\r\n  font-family: inherit;\r\n  color: inherit;\r\n  outline: none;\r\n  transition: border-color 0.2s ease, box-shadow 0.2s ease;\r\n  resize: vertical;\r\n}\r\n\r\n.ph-page.light .pcon-field input,\r\n.ph-page.light .pcon-field textarea {\r\n  background: #f9fafc;\r\n  border: 1px solid #e6eaf1;\r\n}\r\n\r\n.ph-page.dark .pcon-field input,\r\n.ph-page.dark .pcon-field textarea {\r\n  background: rgba(255, 255, 255, 0.04);\r\n  border: 1px solid #242a36;\r\n}\r\n\r\n.pcon-field input:focus,\r\n.pcon-field textarea:focus {\r\n  border-color: var(--ph-accent);\r\n  box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.15);\r\n}\r\n\r\n.pcon-field input.pcon-invalid,\r\n.pcon-field textarea.pcon-invalid {\r\n  border-color: #ef4444;\r\n  box-shadow: 0 0 0 3px rgba(239, 68, 68, 0.12);\r\n}\r\n\r\n.pcon-hint {\r\n  font-size: 11.5px;\r\n  opacity: 0.5;\r\n  align-self: flex-end;\r\n}\r\n\r\n.pcon-field:first-of-type .pcon-hint {\r\n  align-self: flex-start;\r\n}\r\n\r\n.pcon-submit {\r\n  align-self: flex-start;\r\n  margin-top: 4px;\r\n}\r\n\r\n/* ---- Sent confirmation state ---- */\r\n.pcon-sent {\r\n  display: flex;\r\n  flex-direction: column;\r\n  align-items: flex-start;\r\n  gap: 10px;\r\n  padding: 22px;\r\n  border-radius: var(--ph-radius-sm, 12px);\r\n  background: rgba(16, 185, 129, 0.1);\r\n}\r\n\r\n.pcon-sent .anticon {\r\n  font-size: 26px;\r\n  color: #0ea973;\r\n}\r\n\r\n.pcon-sent strong {\r\n  display: block;\r\n  font-size: 14.5px;\r\n}\r\n\r\n.pcon-sent p {\r\n  margin: 4px 0 6px;\r\n  font-size: 13px;\r\n  opacity: 0.75;\r\n}\r\n\r\n.pcon-sent p a {\r\n  color: var(--ph-accent);\r\n  font-weight: 600;\r\n}\r\n\r\n/* ==========================================================================\r\n   RESPONSIVE\r\n   ========================================================================== */\r\n@media (max-width: 900px) {\r\n  .pcon-grid {\r\n    grid-template-columns: 1fr;\r\n  }\r\n}\r\n\r\n@media (max-width: 767px) {\r\n  .pcon-hero { padding: 28px 20px 4px; }\r\n  .pcon-hero-title { font-size: 27px !important; }\r\n  .pcon-hero-lead { font-size: 14px !important; }\r\n\r\n  .pcon-grid { padding: 0 20px; gap: 18px; }\r\n  .pcon-card { padding: 22px 20px; }\r\n}\r\n\r\n@media (max-width: 575px) {\r\n  .pcon-hero-title { font-size: 23px !important; }\r\n  .pcon-card-heading { font-size: 17px; }\r\n  .pcon-submit { width: 100%; justify-content: center; }\r\n}", ""]);
