___CSS_LOADER_EXPORT___.push([module.id, "/* ==========================================================================\r\n   PublicCreditsPage.css\r\n   OCC Alumni — Public \"Credits\" page\r\n   Imports PublicHomePage.css for shared tokens (--ph-accent, .ph-btn,\r\n   .ph-card, .grad, .ph-header, .ph-footer, etc); everything here is\r\n   additive, namespaced with a \"cred-\" prefix so nothing collides with\r\n   the rest of the public site.\r\n   ========================================================================== */\r\n\r\n.cred-page {\r\n  min-height: 100vh;\r\n}\r\n\r\n/* ============ BREADCRUMB: mobile-only ============\r\n   This is the small \"Home / CREDITS\" trail above the page title —\r\n   NOT the header. On desktop/laptop it just repeats what's already in\r\n   the header nav, so it's hidden there and only shown on phones. The\r\n   header itself is never touched by this rule. */\r\n.cred-page .cred-breadcrumb {\r\n  display: none;\r\n}\r\n\r\n@media (max-width: 767px) {\r\n  .cred-page .cred-breadcrumb {\r\n    display: flex;\r\n  }\r\n}\r\n\r\n/* ============ BREADCRUMB + HERO ============ */\r\n.cred-hero {\r\n  max-width: 820px;\r\n  margin: 0 auto;\r\n  padding: 48px 32px 8px;\r\n  text-align: center;\r\n}\r\n\r\n.cred-breadcrumb {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  gap: 8px;\r\n  font-size: 12.5px;\r\n  font-weight: 700;\r\n  letter-spacing: 0.04em;\r\n  text-transform: uppercase;\r\n  opacity: 0.55;\r\n  margin-bottom: 18px;\r\n}\r\n\r\n.cred-breadcrumb button {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 6px;\r\n  background: none;\r\n  border: none;\r\n  padding: 0;\r\n  font: inherit;\r\n  color: inherit;\r\n  cursor: pointer;\r\n  opacity: 0.85;\r\n}\r\n\r\n.cred-breadcrumb button:hover {\r\n  color: var(--ph-accent);\r\n  opacity: 1;\r\n}\r\n\r\n.cred-breadcrumb-current {\r\n  color: var(--ph-accent);\r\n}\r\n\r\n.cred-hero-title {\r\n  font-size: 40px !important;\r\n  font-weight: 900 !important;\r\n  margin: 0 0 12px !important;\r\n  color: inherit !important;\r\n}\r\n\r\n.cred-hero-lead {\r\n  font-size: 15.5px !important;\r\n  opacity: 0.72;\r\n  color: inherit !important;\r\n  max-width: 620px;\r\n  margin: 0 auto !important;\r\n}\r\n\r\n/* ============ SECTION ============ */\r\n.cred-section {\r\n  padding-top: 12px;\r\n  padding-bottom: 8px;\r\n}\r\n\r\n/* ============ TEAM GRID ============ */\r\n.cred-team-grid {\r\n  max-width: 1080px;\r\n  margin: 0 auto;\r\n  padding: 0 24px;\r\n  display: grid;\r\n  grid-template-columns: repeat(2, 1fr);\r\n  gap: 22px;\r\n}\r\n\r\n.cred-card {\r\n  border-radius: var(--ph-radius-md, 18px);\r\n  padding: 26px;\r\n  display: flex;\r\n  gap: 20px;\r\n  align-items: flex-start;\r\n  transition: transform 0.25s ease, box-shadow 0.25s ease;\r\n}\r\n\r\n.ph-page.light .cred-card {\r\n  background: #ffffff;\r\n  border: 1px solid #edf0f5;\r\n  box-shadow: 0 10px 30px rgba(2, 6, 23, 0.05);\r\n}\r\n\r\n.ph-page.dark .cred-card {\r\n  background: rgba(18, 22, 32, 0.75);\r\n  border: 1px solid #242a36;\r\n  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.3);\r\n}\r\n\r\n.cred-card:hover {\r\n  transform: translateY(-4px);\r\n}\r\n\r\n.ph-page.light .cred-card:hover { box-shadow: 0 20px 40px rgba(2, 6, 23, 0.1); }\r\n.ph-page.dark .cred-card:hover { box-shadow: 0 20px 40px rgba(0, 0, 0, 0.45); }\r\n\r\n/* ---- 2x2 (square, resume-style) avatar ---- */\r\n.cred-avatar {\r\n  flex-shrink: 0;\r\n  width: 96px;\r\n  height: 96px;\r\n  border-radius: 16px;\r\n  overflow: hidden;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  background: linear-gradient(135deg, var(--ph-accent), var(--ph-accent-3) 55%, var(--ph-accent-2));\r\n}\r\n\r\n.ph-page.light .cred-avatar {\r\n  box-shadow: 0 6px 18px rgba(2, 6, 23, 0.1);\r\n}\r\n\r\n.ph-page.dark .cred-avatar {\r\n  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.35);\r\n}\r\n\r\n.cred-avatar img {\r\n  width: 100%;\r\n  height: 100%;\r\n  -o-object-fit: cover;\r\n     object-fit: cover;\r\n  /* Anchored to the top, not centered — headshot-style photos already\r\n     frame the face near the top with the body/gown filling the rest\r\n     below. Centering a tall portrait photo (like a full 4:5 photo vs.\r\n     a square one) would crop equally off the top and bottom, which\r\n     clips straight into the hairline on any photo that doesn't have\r\n     much headroom to begin with. Anchoring top keeps the whole head\r\n     intact and only trims extra shoulder/gown space off the bottom\r\n     instead — consistent framing across every member's card\r\n     regardless of their original photo's aspect ratio. */\r\n  -o-object-position: center top;\r\n     object-position: center top;\r\n  display: block;\r\n}\r\n\r\n.cred-avatar-fallback {\r\n  font-size: 30px;\r\n  font-weight: 800;\r\n  color: #ffffff;\r\n  letter-spacing: 0.02em;\r\n}\r\n\r\n.cred-card-body {\r\n  flex: 1;\r\n  min-width: 0;\r\n}\r\n\r\n.cred-role-tag {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 6px;\r\n  font-size: 11.5px;\r\n  font-weight: 700;\r\n  letter-spacing: 0.02em;\r\n  padding: 4px 11px;\r\n  border-radius: 999px;\r\n  color: var(--ph-accent);\r\n  margin-bottom: 10px;\r\n}\r\n\r\n.ph-page.light .cred-role-tag {\r\n  background: #f5f7fb;\r\n  border: 1px solid #e6eaf1;\r\n}\r\n\r\n.ph-page.dark .cred-role-tag {\r\n  background: rgba(255, 255, 255, 0.05);\r\n  border: 1px solid #242a36;\r\n}\r\n\r\n.cred-card-name {\r\n  font-size: 18px !important;\r\n  font-weight: 800 !important;\r\n  margin: 0 0 8px !important;\r\n  color: inherit !important;\r\n}\r\n\r\n.cred-card-desc {\r\n  font-size: 13.5px !important;\r\n  line-height: 1.6 !important;\r\n  opacity: 0.72;\r\n  color: inherit !important;\r\n  margin: 0 !important;\r\n}\r\n\r\n/* ============ SPECIAL THANKS ============ */\r\n.cred-thanks-section {\r\n  padding-top: 28px;\r\n  padding-bottom: 60px;\r\n}\r\n\r\n.cred-thanks-title {\r\n  text-align: center;\r\n  font-size: 24px !important;\r\n  font-weight: 800 !important;\r\n  margin: 0 0 22px !important;\r\n  color: inherit !important;\r\n}\r\n\r\n.cred-thanks-grid {\r\n  max-width: 1080px;\r\n  margin: 0 auto;\r\n  padding: 0 24px;\r\n  display: grid;\r\n  grid-template-columns: repeat(3, 1fr);\r\n  gap: 20px;\r\n}\r\n\r\n.cred-thanks-card {\r\n  border-radius: var(--ph-radius-md, 18px);\r\n  padding: 24px;\r\n}\r\n\r\n.ph-page.light .cred-thanks-card {\r\n  background: #f8f9fc;\r\n  border: 1px solid #edf0f5;\r\n}\r\n\r\n.ph-page.dark .cred-thanks-card {\r\n  background: rgba(255, 255, 255, 0.03);\r\n  border: 1px solid #242a36;\r\n}\r\n\r\n.cred-thanks-heading {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 9px;\r\n  font-size: 15px;\r\n  font-weight: 800;\r\n  margin-bottom: 10px;\r\n  color: inherit;\r\n}\r\n\r\n.cred-thanks-heading .anticon {\r\n  color: var(--ph-accent);\r\n}\r\n\r\n.cred-thanks-p {\r\n  font-size: 13px !important;\r\n  line-height: 1.6 !important;\r\n  opacity: 0.68;\r\n  color: inherit !important;\r\n  margin: 0 !important;\r\n}\r\n\r\n/* ==========================================================================\r\n   RESPONSIVE\r\n   ========================================================================== */\r\n@media (max-width: 900px) {\r\n  .cred-team-grid { grid-template-columns: 1fr; }\r\n  .cred-thanks-grid { grid-template-columns: 1fr; }\r\n}\r\n\r\n@media (max-width: 767px) {\r\n  .cred-hero { padding: 28px 20px 4px; }\r\n  .cred-hero-title { font-size: 27px !important; }\r\n  .cred-hero-lead { font-size: 14px !important; }\r\n\r\n  .cred-team-grid { padding: 0 20px; gap: 16px; }\r\n  .cred-card { padding: 20px; gap: 16px; }\r\n  .cred-avatar { width: 80px; height: 80px; border-radius: 14px; }\r\n  .cred-avatar-fallback { font-size: 24px; }\r\n\r\n  .cred-thanks-grid { padding: 0 20px; }\r\n}\r\n\r\n@media (max-width: 575px) {\r\n  .cred-hero-title { font-size: 23px !important; }\r\n  .cred-card { flex-direction: column; align-items: center; text-align: center; }\r\n  .cred-card-body { width: 100%; }\r\n}", ""]);
