___CSS_LOADER_EXPORT___.push([module.id, "/* ==========================================================================\r\n   PublicEventsPage.css\r\n   OCC Alumni — Public Events Page (Upcoming / Ongoing / Completed / Featured)\r\n   Imports PublicHomePage.css for shared tokens/header/footer/.ph-card/.ph-btn;\r\n   everything here is additive, namespaced with a \"pev-\" prefix so nothing\r\n   collides with the homepage's own rules.\r\n   ========================================================================== */\r\n\r\n/* ============ PAGE HERO / JUMP-TO DROPDOWN ============ */\r\n.pev-hero {\r\n  max-width: 900px;\r\n  margin: 0 auto;\r\n  padding: 48px 32px 8px;\r\n  text-align: center;\r\n}\r\n\r\n.pev-hero-eyebrow {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n  padding: 6px 14px;\r\n  border-radius: 999px;\r\n  font-size: 13px;\r\n  font-weight: 700;\r\n  letter-spacing: 0.02em;\r\n  background: rgba(79, 70, 229, 0.1);\r\n  color: var(--ph-accent);\r\n  margin-bottom: 18px;\r\n}\r\n\r\n.pev-hero-title {\r\n  font-size: 40px !important;\r\n  font-weight: 900 !important;\r\n  margin: 0 0 12px !important;\r\n  color: inherit !important;\r\n}\r\n\r\n.pev-hero-lead {\r\n  font-size: 15.5px !important;\r\n  opacity: 0.7;\r\n  color: inherit !important;\r\n  max-width: 640px;\r\n  margin: 0 auto 28px !important;\r\n}\r\n\r\n/* ============ SECTION spacing tweak ============ */\r\n.pev-section {\r\n  scroll-margin-top: calc(var(--ph-header-h) + 16px);\r\n}\r\n\r\n.pev-section + .pev-section {\r\n  border-top: 1px solid transparent;\r\n}\r\n\r\n.ph-page.light .pev-section + .pev-section {\r\n  border-top-color: #edf0f5;\r\n}\r\n\r\n.ph-page.dark .pev-section + .pev-section {\r\n  border-top-color: #1d2230;\r\n}\r\n\r\n/* ============ EVENT CARD ============ */\r\n/* Overrides .ph-card's row layout (icon + text side by side) with a\r\n   stacked card: media on top, full details below — there is simply\r\n   more content per card here than the homepage teaser cards. */\r\n.pev-card {\r\n  flex-direction: column;\r\n  padding: 0;\r\n  overflow: hidden;\r\n  gap: 0;\r\n  cursor: default;\r\n}\r\n\r\n.pev-card:hover {\r\n  transform: translateY(-4px);\r\n}\r\n\r\n/* ---- Media / image swapper ---- */\r\n.pev-media {\r\n  position: relative;\r\n  width: 100%;\r\n  height: 190px;\r\n  overflow: hidden;\r\n  background: linear-gradient(135deg, rgba(79, 70, 229, 0.12), rgba(14, 165, 233, 0.12));\r\n}\r\n\r\n.pev-media img {\r\n  width: 100%;\r\n  height: 100%;\r\n  -o-object-fit: cover;\r\n     object-fit: cover;\r\n  display: block;\r\n}\r\n\r\n.pev-media-empty {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n}\r\n\r\n.pev-media-empty .anticon {\r\n  font-size: 34px;\r\n  color: var(--ph-accent);\r\n}\r\n\r\n.pev-media-carousel .ant-carousel,\r\n.pev-media-carousel .slick-slider,\r\n.pev-media-carousel .slick-list,\r\n.pev-media-carousel .slick-track,\r\n.pev-media-carousel .slick-slide > div {\r\n  height: 190px;\r\n}\r\n\r\n.pev-slide {\r\n  height: 190px;\r\n}\r\n\r\n.pev-media-carousel .slick-dots {\r\n  bottom: 8px;\r\n}\r\n\r\n.pev-media-carousel .slick-dots li button {\r\n  background: rgba(255, 255, 255, 0.6);\r\n}\r\n\r\n.pev-media-carousel .slick-dots li.slick-active button {\r\n  background: #ffffff;\r\n}\r\n\r\n.pev-media-count {\r\n  position: absolute;\r\n  top: 10px;\r\n  right: 10px;\r\n  z-index: 2;\r\n  font-size: 11.5px;\r\n  font-weight: 700;\r\n  padding: 3px 9px;\r\n  border-radius: 999px;\r\n  background: rgba(0, 0, 0, 0.55);\r\n  color: #ffffff;\r\n  pointer-events: none;\r\n}\r\n\r\n/* ---- Body ---- */\r\n.pev-card-body {\r\n  padding: 18px 20px 20px;\r\n  display: flex;\r\n  flex-direction: column;\r\n  flex: 1;\r\n}\r\n\r\n.pev-card-tags {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  gap: 8px;\r\n  margin-bottom: 10px;\r\n}\r\n\r\n.pev-badge,\r\n.pev-type-tag {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 5px;\r\n  font-size: 11.5px;\r\n  font-weight: 700;\r\n  padding: 4px 10px;\r\n  border-radius: 999px;\r\n  line-height: 1.4;\r\n}\r\n\r\n.pev-type-tag {\r\n  background: rgba(124, 58, 237, 0.1);\r\n  color: var(--ph-accent-3);\r\n}\r\n\r\n/* Category chip reuses the same pill shape as .pev-type-tag but in a\r\n   different tone, so Type vs. Category read as two distinct pieces\r\n   of info at a glance instead of blending into one long chip. */\r\n.pev-category-tag {\r\n  background: rgba(14, 165, 233, 0.1);\r\n  color: var(--ph-accent-2);\r\n}\r\n\r\n.pev-badge.is-upcoming {\r\n  background: rgba(14, 165, 233, 0.12);\r\n  color: var(--ph-accent-2);\r\n}\r\n\r\n.pev-badge.is-ongoing {\r\n  background: rgba(16, 185, 129, 0.14);\r\n  color: #0ea973;\r\n}\r\n\r\n.pev-badge.is-completed {\r\n  background: rgba(107, 114, 128, 0.16);\r\n  color: #6b7280;\r\n}\r\n\r\n.pev-badge.is-featured {\r\n  background: rgba(245, 158, 11, 0.14);\r\n  color: var(--ph-warm);\r\n}\r\n\r\n/* \"Live Now\" gets a soft pulse to draw the eye, same visual language\r\n   as the \"Launching Soon\" badge already used on the homepage. */\r\n.pev-badge.is-ongoing::before {\r\n  content: \"\";\r\n  width: 6px;\r\n  height: 6px;\r\n  border-radius: 50%;\r\n  background: #0ea973;\r\n  margin-right: 2px;\r\n  animation: pevPulse 1.6s ease-in-out infinite;\r\n}\r\n\r\n@keyframes pevPulse {\r\n  0%, 100% { opacity: 1; transform: scale(1); }\r\n  50% { opacity: 0.4; transform: scale(0.7); }\r\n}\r\n\r\n.pev-card-title {\r\n  font-size: 17px !important;\r\n  font-weight: 800 !important;\r\n  margin: 0 0 6px !important;\r\n  color: inherit !important;\r\n}\r\n\r\n.pev-card-desc {\r\n  font-size: 13.5px !important;\r\n  opacity: 0.72;\r\n  margin: 0 0 14px !important;\r\n  color: inherit !important;\r\n  display: -webkit-box;\r\n  -webkit-line-clamp: 3;\r\n  -webkit-box-orient: vertical;\r\n  overflow: hidden;\r\n}\r\n\r\n.pev-card-facts {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 8px;\r\n  padding-top: 12px;\r\n  margin-bottom: 14px;\r\n}\r\n\r\n.ph-page.light .pev-card-facts {\r\n  border-top: 1px dashed #e6eaf1;\r\n}\r\n\r\n.ph-page.dark .pev-card-facts {\r\n  border-top: 1px dashed #242a36;\r\n}\r\n\r\n.pev-fact {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 9px;\r\n  font-size: 13px;\r\n  opacity: 0.85;\r\n}\r\n\r\n.pev-fact .anticon {\r\n  color: var(--ph-accent);\r\n  flex-shrink: 0;\r\n}\r\n\r\n/* ---- Footer: status message + actions ---- */\r\n.pev-card-footer {\r\n  margin-top: auto;\r\n}\r\n\r\n.pev-status-msg {\r\n  font-size: 12.5px !important;\r\n  opacity: 0.65;\r\n  margin: 0 0 12px !important;\r\n  line-height: 1.5;\r\n  display: flex;\r\n  align-items: flex-start;\r\n  gap: 6px;\r\n}\r\n\r\n.pev-card-actions {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  gap: 10px;\r\n}\r\n\r\n.pev-card-actions .ph-btn {\r\n  flex: 1 1 auto;\r\n  justify-content: center;\r\n  font-size: 13.5px;\r\n  padding: 9px 16px;\r\n}\r\n\r\n/* ==========================================================================\r\n   RESPONSIVE — mobile portrait & landscape\r\n   ========================================================================== */\r\n\r\n/* Tablets / small laptops */\r\n@media (max-width: 1199px) {\r\n  .pev-hero { padding: 42px 24px 8px; }\r\n}\r\n\r\n@media (max-width: 991px) {\r\n  .pev-hero-title { font-size: 32px !important; }\r\n}\r\n\r\n/* Phones — portrait */\r\n@media (max-width: 767px) {\r\n  .pev-hero { padding: 32px 20px 4px; }\r\n  .pev-hero-title { font-size: 26px !important; }\r\n  .pev-hero-lead { font-size: 14px !important; }\r\n\r\n  .pev-media,\r\n  .pev-media-carousel .ant-carousel,\r\n  .pev-media-carousel .slick-slider,\r\n  .pev-media-carousel .slick-list,\r\n  .pev-media-carousel .slick-track,\r\n  .pev-media-carousel .slick-slide > div,\r\n  .pev-slide {\r\n    height: 170px;\r\n  }\r\n\r\n  .pev-card-body { padding: 16px 16px 18px; }\r\n  .pev-card-actions { flex-direction: column; }\r\n  .pev-card-actions .ph-btn { width: 100%; }\r\n}\r\n\r\n@media (max-width: 575px) {\r\n  .pev-hero-eyebrow { font-size: 12px; }\r\n  .pev-hero-title { font-size: 23px !important; }\r\n  .pev-card-title { font-size: 16px !important; }\r\n}\r\n\r\n@media (max-width: 374px) {\r\n  .pev-hero { padding: 26px 16px 4px; }\r\n  .pev-card-facts { gap: 6px; }\r\n}\r\n\r\n/* Phones — landscape (short viewport height, wide width) */\r\n@media (max-width: 900px) and (orientation: landscape) {\r\n  .pev-hero { padding: 20px 24px 4px; }\r\n  .pev-hero-title { font-size: 24px !important; margin-bottom: 6px !important; }\r\n  .pev-hero-lead { margin-bottom: 16px !important; }\r\n\r\n  .pev-media,\r\n  .pev-media-carousel .ant-carousel,\r\n  .pev-media-carousel .slick-slider,\r\n  .pev-media-carousel .slick-list,\r\n  .pev-media-carousel .slick-track,\r\n  .pev-media-carousel .slick-slide > div,\r\n  .pev-slide {\r\n    height: 150px;\r\n  }\r\n\r\n  .pev-card-actions { flex-direction: row; }\r\n  .pev-card-actions .ph-btn { width: auto; }\r\n}\r\n\r\n@media (prefers-reduced-motion: reduce) {\r\n  .pev-badge.is-ongoing::before { animation: none; }\r\n}", ""]);
