___CSS_LOADER_EXPORT___.push([module.id, "/* ==========================================================================\r\n   PublicJobPostsPage.css\r\n   OCC Alumni — Public Job Posts Page (Full-time / Part-time / Contract)\r\n   Imports PublicHomePage.css for shared tokens/header/footer/.ph-card/.ph-btn;\r\n   everything here is additive, namespaced with a \"pjp-\" prefix so nothing\r\n   collides with the homepage's or events page's own rules.\r\n   ========================================================================== */\r\n\r\n/* ============ PAGE HERO / JUMP-TO + SORT CONTROLS ============ */\r\n.pjp-hero {\r\n  max-width: 900px;\r\n  margin: 0 auto;\r\n  padding: 48px 32px 8px;\r\n  text-align: center;\r\n}\r\n\r\n.pjp-hero-eyebrow {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n  padding: 6px 14px;\r\n  border-radius: 999px;\r\n  font-size: 13px;\r\n  font-weight: 700;\r\n  letter-spacing: 0.02em;\r\n  background: rgba(79, 70, 229, 0.1);\r\n  color: var(--ph-accent);\r\n  margin-bottom: 18px;\r\n}\r\n\r\n.pjp-hero-title {\r\n  font-size: 40px !important;\r\n  font-weight: 900 !important;\r\n  margin: 0 0 12px !important;\r\n  color: inherit !important;\r\n}\r\n\r\n.pjp-hero-lead {\r\n  font-size: 15.5px !important;\r\n  opacity: 0.7;\r\n  color: inherit !important;\r\n  max-width: 640px;\r\n  margin: 0 auto 28px !important;\r\n}\r\n\r\n\r\n\r\n/* ============ SECTION spacing tweak ============ */\r\n.pjp-section {\r\n  scroll-margin-top: calc(var(--ph-header-h) + 16px);\r\n}\r\n\r\n.pjp-section + .pjp-section {\r\n  border-top: 1px solid transparent;\r\n}\r\n\r\n.ph-page.light .pjp-section + .pjp-section {\r\n  border-top-color: #edf0f5;\r\n}\r\n\r\n.ph-page.dark .pjp-section + .pjp-section {\r\n  border-top-color: #1d2230;\r\n}\r\n\r\n/* ============ JOB CARD ============ */\r\n/* Overrides .ph-card's row layout (icon + text side by side) with a\r\n   stacked card: banner on top, full details below — there is simply\r\n   more content per card here than the homepage teaser cards. */\r\n.pjp-card {\r\n  flex-direction: column;\r\n  padding: 0;\r\n  overflow: hidden;\r\n  gap: 0;\r\n  cursor: default;\r\n}\r\n\r\n.pjp-card:hover {\r\n  transform: translateY(-4px);\r\n}\r\n\r\n/* ---- Banner image ---- */\r\n.pjp-media {\r\n  position: relative;\r\n  width: 100%;\r\n  height: 190px;\r\n  overflow: hidden;\r\n  background: linear-gradient(135deg, rgba(79, 70, 229, 0.12), rgba(14, 165, 233, 0.12));\r\n}\r\n\r\n.pjp-media img {\r\n  width: 100%;\r\n  height: 100%;\r\n  -o-object-fit: cover;\r\n     object-fit: cover;\r\n  display: block;\r\n}\r\n\r\n.pjp-media-empty {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n}\r\n\r\n.pjp-media-empty .anticon {\r\n  font-size: 34px;\r\n  color: var(--ph-accent);\r\n}\r\n\r\n/* ---- Body ---- */\r\n.pjp-card-body {\r\n  padding: 18px 20px 20px;\r\n  display: flex;\r\n  flex-direction: column;\r\n  flex: 1;\r\n}\r\n\r\n.pjp-card-tags {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  gap: 8px;\r\n  margin-bottom: 10px;\r\n}\r\n\r\n.pjp-badge {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 5px;\r\n  font-size: 11.5px;\r\n  font-weight: 700;\r\n  padding: 4px 10px;\r\n  border-radius: 999px;\r\n  line-height: 1.4;\r\n}\r\n\r\n.pjp-badge.is-fulltime {\r\n  background: rgba(16, 185, 129, 0.14);\r\n  color: #0ea973;\r\n}\r\n\r\n.pjp-badge.is-parttime {\r\n  background: rgba(14, 165, 233, 0.12);\r\n  color: var(--ph-accent-2);\r\n}\r\n\r\n.pjp-badge.is-contract {\r\n  background: rgba(245, 158, 11, 0.14);\r\n  color: var(--ph-warm);\r\n}\r\n\r\n.pjp-badge.is-general {\r\n  background: rgba(124, 58, 237, 0.1);\r\n  color: var(--ph-accent-3);\r\n}\r\n\r\n.pjp-badge.is-closed {\r\n  background: rgba(107, 114, 128, 0.16);\r\n  color: #6b7280;\r\n}\r\n\r\n.pjp-card-title {\r\n  font-size: 17px !important;\r\n  font-weight: 800 !important;\r\n  margin: 0 0 8px !important;\r\n  color: inherit !important;\r\n}\r\n\r\n.pjp-card-company {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 7px;\r\n  font-size: 13.5px;\r\n  margin-bottom: 10px;\r\n}\r\n\r\n.pjp-card-company .anticon {\r\n  color: var(--ph-accent);\r\n}\r\n\r\n.pjp-card-desc {\r\n  font-size: 13.5px !important;\r\n  opacity: 0.72;\r\n  margin: 0 0 14px !important;\r\n  color: inherit !important;\r\n  display: -webkit-box;\r\n  -webkit-line-clamp: 3;\r\n  -webkit-box-orient: vertical;\r\n  overflow: hidden;\r\n}\r\n\r\n.pjp-card-facts {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 8px;\r\n  padding-top: 12px;\r\n  margin-bottom: 14px;\r\n}\r\n\r\n.ph-page.light .pjp-card-facts {\r\n  border-top: 1px dashed #e6eaf1;\r\n}\r\n\r\n.ph-page.dark .pjp-card-facts {\r\n  border-top: 1px dashed #242a36;\r\n}\r\n\r\n.pjp-fact {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 9px;\r\n  font-size: 13px;\r\n  opacity: 0.85;\r\n}\r\n\r\n.pjp-fact .anticon {\r\n  color: var(--ph-accent);\r\n  flex-shrink: 0;\r\n}\r\n\r\n/* ---- Footer: status message + actions ---- */\r\n.pjp-card-footer {\r\n  margin-top: auto;\r\n}\r\n\r\n.pjp-status-msg {\r\n  font-size: 12.5px !important;\r\n  opacity: 0.65;\r\n  margin: 0 0 12px !important;\r\n  line-height: 1.5;\r\n  display: flex;\r\n  align-items: flex-start;\r\n  gap: 6px;\r\n}\r\n\r\n.pjp-card-actions {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  gap: 10px;\r\n}\r\n\r\n.pjp-card-actions .ph-btn {\r\n  flex: 1 1 auto;\r\n  justify-content: center;\r\n  font-size: 13.5px;\r\n  padding: 9px 16px;\r\n}\r\n\r\n/* ==========================================================================\r\n   RESPONSIVE — mobile portrait & landscape\r\n   ========================================================================== */\r\n\r\n/* Tablets / small laptops */\r\n@media (max-width: 1199px) {\r\n  .pjp-hero { padding: 42px 24px 8px; }\r\n}\r\n\r\n@media (max-width: 991px) {\r\n  .pjp-hero-title { font-size: 32px !important; }\r\n}\r\n\r\n/* Phones — portrait */\r\n@media (max-width: 767px) {\r\n  .pjp-hero { padding: 32px 20px 4px; }\r\n  .pjp-hero-title { font-size: 26px !important; }\r\n  .pjp-hero-lead { font-size: 14px !important; }\r\n\r\n  .pjp-media { height: 170px; }\r\n\r\n  .pjp-card-body { padding: 16px 16px 18px; }\r\n  .pjp-card-actions { flex-direction: column; }\r\n  .pjp-card-actions .ph-btn { width: 100%; }\r\n}\r\n\r\n@media (max-width: 575px) {\r\n  .pjp-hero-eyebrow { font-size: 12px; }\r\n  .pjp-hero-title { font-size: 23px !important; }\r\n  .pjp-card-title { font-size: 16px !important; }\r\n}\r\n\r\n@media (max-width: 374px) {\r\n  .pjp-hero { padding: 26px 16px 4px; }\r\n  .pjp-card-facts { gap: 6px; }\r\n}\r\n\r\n/* Phones — landscape (short viewport height, wide width) */\r\n@media (max-width: 900px) and (orientation: landscape) {\r\n  .pjp-hero { padding: 20px 24px 4px; }\r\n  .pjp-hero-title { font-size: 24px !important; margin-bottom: 6px !important; }\r\n  .pjp-hero-lead { margin-bottom: 16px !important; }\r\n\r\n  .pjp-media { height: 150px; }\r\n\r\n  .pjp-card-actions { flex-direction: row; }\r\n  .pjp-card-actions .ph-btn { width: auto; }\r\n}", ""]);
