___CSS_LOADER_EXPORT___.push([module.id, "/* ==========================================================================\r\n   PublicOccServicesPage.css\r\n   OCC Alumni — Public \"OCC Services\" directory page\r\n   Imports PublicHomePage.css for shared tokens (--ph-accent, .ph-btn,\r\n   .ph-card, .grad, .ph-header, .ph-footer, etc); everything here is\r\n   additive, namespaced with an \"occsvc-\" prefix so nothing collides\r\n   with the rest of the public site.\r\n   ========================================================================== */\r\n\r\n.occsvc-page {\r\n  min-height: 100vh;\r\n}\r\n\r\n/* ==========================================================================\r\n   INTRO\r\n   ========================================================================== */\r\n\r\n.occsvc-intro {\r\n  position: relative;\r\n  padding: 28px 24px 48px;\r\n  overflow: hidden;\r\n  text-align: center;\r\n}\r\n\r\n.occsvc-intro-bg {\r\n  position: absolute;\r\n  inset: 0;\r\n  z-index: 0;\r\n  background: linear-gradient(\r\n    135deg,\r\n    rgba(79, 70, 229, 0.08),\r\n    rgba(14, 165, 233, 0.08) 55%,\r\n    rgba(124, 58, 237, 0.08)\r\n  );\r\n}\r\n\r\n.ph-page.dark .occsvc-intro-bg {\r\n  background: linear-gradient(\r\n    135deg,\r\n    rgba(79, 70, 229, 0.14),\r\n    rgba(14, 165, 233, 0.1) 55%,\r\n    rgba(124, 58, 237, 0.14)\r\n  );\r\n}\r\n\r\n.occsvc-intro-inner {\r\n  position: relative;\r\n  z-index: 1;\r\n  max-width: 760px;\r\n  margin: 0 auto;\r\n}\r\n\r\n.occsvc-intro-eyebrow {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n  font-size: 13px;\r\n  font-weight: 700;\r\n  letter-spacing: 0.02em;\r\n  padding: 7px 16px;\r\n  border-radius: 999px;\r\n  margin-bottom: 20px;\r\n  color: var(--ph-accent);\r\n}\r\n\r\n.ph-page.light .occsvc-intro-eyebrow {\r\n  background: #f5f7fb;\r\n  border: 1px solid #e6eaf1;\r\n}\r\n\r\n.ph-page.dark .occsvc-intro-eyebrow {\r\n  background: rgba(255, 255, 255, 0.05);\r\n  border: 1px solid #242a36;\r\n}\r\n\r\n.occsvc-intro-title {\r\n  font-size: 40px !important;\r\n  font-weight: 900 !important;\r\n  line-height: 1.15 !important;\r\n  margin: 0 0 18px !important;\r\n  color: inherit !important;\r\n}\r\n\r\n.occsvc-intro-lead {\r\n  font-size: 16.5px !important;\r\n  line-height: 1.65 !important;\r\n  opacity: 0.82;\r\n  color: inherit !important;\r\n  margin: 0 auto 14px !important;\r\n  max-width: 620px;\r\n}\r\n\r\n.occsvc-intro-sub {\r\n  font-size: 14.5px !important;\r\n  line-height: 1.65 !important;\r\n  opacity: 0.62;\r\n  color: inherit !important;\r\n  margin: 0 auto !important;\r\n  max-width: 560px;\r\n}\r\n\r\n/* ==========================================================================\r\n   SERVICES GRID\r\n   ========================================================================== */\r\n\r\n.occsvc-section {\r\n  padding-top: 8px;\r\n  padding-bottom: 72px;\r\n}\r\n\r\n.occsvc-status-row {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: space-between;\r\n  gap: 16px;\r\n  max-width: 1180px;\r\n  margin: 0 auto 22px;\r\n  padding: 0 24px;\r\n}\r\n\r\n.occsvc-status-note {\r\n  font-size: 13px;\r\n  opacity: 0.6;\r\n  max-width: 640px;\r\n  line-height: 1.5;\r\n}\r\n\r\n.occsvc-recheck-btn {\r\n  flex-shrink: 0;\r\n  white-space: nowrap;\r\n}\r\n\r\n.occsvc-status-pill {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 6px;\r\n  align-self: flex-start;\r\n  font-size: 12px;\r\n  font-weight: 700;\r\n  padding: 4px 10px 4px 8px;\r\n  border-radius: 999px;\r\n}\r\n\r\n.occsvc-status-dot {\r\n  width: 7px;\r\n  height: 7px;\r\n  border-radius: 50%;\r\n  flex-shrink: 0;\r\n}\r\n\r\n.occsvc-status-checking {\r\n  color: #64748b;\r\n}\r\n\r\n.ph-page.light .occsvc-status-checking { background: #f1f3f7; }\r\n.ph-page.dark .occsvc-status-checking { background: rgba(255, 255, 255, 0.06); }\r\n\r\n.occsvc-status-checking .occsvc-status-dot {\r\n  background: #94a3b8;\r\n  animation: occsvc-pulse 1.1s ease-in-out infinite;\r\n}\r\n\r\n.occsvc-status-up {\r\n  color: #15803d;\r\n}\r\n\r\n.ph-page.light .occsvc-status-up { background: #ecfdf3; }\r\n.ph-page.dark .occsvc-status-up { background: rgba(21, 128, 61, 0.16); color: #4ade80; }\r\n\r\n.occsvc-status-up .occsvc-status-dot {\r\n  background: #22c55e;\r\n}\r\n\r\n.occsvc-status-down {\r\n  color: #b91c1c;\r\n}\r\n\r\n.ph-page.light .occsvc-status-down { background: #fef2f2; }\r\n.ph-page.dark .occsvc-status-down { background: rgba(185, 28, 28, 0.16); color: #f87171; }\r\n\r\n.occsvc-status-down .occsvc-status-dot {\r\n  background: #ef4444;\r\n}\r\n\r\n@keyframes occsvc-pulse {\r\n  0%, 100% { opacity: 1; transform: scale(1); }\r\n  50% { opacity: 0.4; transform: scale(0.75); }\r\n}\r\n\r\n.occsvc-grid {\r\n  display: grid;\r\n  grid-template-columns: repeat(3, 1fr);\r\n  gap: 22px;\r\n  max-width: 1180px;\r\n  margin: 0 auto;\r\n  padding: 0 24px;\r\n}\r\n\r\n.occsvc-card {\r\n  border-radius: var(--ph-radius-md, 18px);\r\n  padding: 26px;\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 14px;\r\n  transition: transform 0.25s ease, box-shadow 0.25s ease;\r\n  scroll-margin-top: calc(var(--ph-header-h) + 16px);\r\n}\r\n\r\n.ph-page.light .occsvc-card {\r\n  background: #ffffff;\r\n  border: 1px solid #edf0f5;\r\n  box-shadow: 0 10px 30px rgba(2, 6, 23, 0.05);\r\n}\r\n\r\n.ph-page.dark .occsvc-card {\r\n  background: rgba(18, 22, 32, 0.75);\r\n  border: 1px solid #242a36;\r\n  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.3);\r\n}\r\n\r\n.occsvc-card:hover {\r\n  transform: translateY(-4px);\r\n}\r\n\r\n.ph-page.light .occsvc-card:hover {\r\n  box-shadow: 0 20px 40px rgba(2, 6, 23, 0.1);\r\n}\r\n\r\n.ph-page.dark .occsvc-card:hover {\r\n  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.45);\r\n}\r\n\r\n/* ---- Deep-link highlight ---- */\r\n/* Briefly applied when a visitor lands here via ?system=<id> from the\r\n   Home header's OCC Services dropdown, so the card they picked is\r\n   obvious at a glance among the other four before it fades back to\r\n   normal on its own. */\r\n.occsvc-card-highlight {\r\n  animation: occsvc-card-highlight-pulse 2.4s ease;\r\n}\r\n\r\n.ph-page.light .occsvc-card-highlight {\r\n  box-shadow: 0 0 0 3px var(--ph-accent), 0 20px 40px rgba(2, 6, 23, 0.1);\r\n}\r\n\r\n.ph-page.dark .occsvc-card-highlight {\r\n  box-shadow: 0 0 0 3px var(--ph-accent), 0 20px 40px rgba(0, 0, 0, 0.45);\r\n}\r\n\r\n@keyframes occsvc-card-highlight-pulse {\r\n  0% { transform: translateY(0); }\r\n  15% { transform: translateY(-4px); }\r\n  100% { transform: translateY(0); }\r\n}\r\n\r\n@media (prefers-reduced-motion: reduce) {\r\n  .occsvc-card-highlight {\r\n    animation: none;\r\n  }\r\n}\r\n\r\n.occsvc-card-top {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: space-between;\r\n  gap: 10px;\r\n}\r\n\r\n/* Every card shares this exact same OCC logo treatment on purpose —\r\n   these are different doors, same campus, same mark. */\r\n.occsvc-card-logo-wrap {\r\n  flex-shrink: 0;\r\n  width: 60px;\r\n  height: 60px;\r\n  border-radius: 14px;\r\n  overflow: hidden;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  background: linear-gradient(135deg, rgba(79, 70, 229, 0.12), rgba(14, 165, 233, 0.12));\r\n}\r\n\r\n.occsvc-card-logo-wrap img {\r\n  width: 72%;\r\n  height: 72%;\r\n  -o-object-fit: contain;\r\n     object-fit: contain;\r\n}\r\n\r\n.occsvc-card-tag {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 6px;\r\n  font-size: 11.5px;\r\n  font-weight: 700;\r\n  letter-spacing: 0.02em;\r\n  padding: 5px 10px;\r\n  border-radius: 999px;\r\n  color: var(--ph-accent);\r\n  white-space: nowrap;\r\n}\r\n\r\n.ph-page.light .occsvc-card-tag {\r\n  background: #f5f7fb;\r\n  border: 1px solid #e6eaf1;\r\n}\r\n\r\n.ph-page.dark .occsvc-card-tag {\r\n  background: rgba(255, 255, 255, 0.05);\r\n  border: 1px solid #242a36;\r\n  color: #a5a1f7;\r\n}\r\n\r\n.occsvc-card-body {\r\n  flex: 1;\r\n  min-width: 0;\r\n}\r\n\r\n.occsvc-card-title {\r\n  font-size: 18px !important;\r\n  font-weight: 800 !important;\r\n  margin: 0 0 8px !important;\r\n  color: inherit !important;\r\n}\r\n\r\n.occsvc-card-desc {\r\n  font-size: 13.5px !important;\r\n  opacity: 0.7;\r\n  margin: 0 0 12px !important;\r\n  color: inherit !important;\r\n  line-height: 1.55;\r\n}\r\n\r\n.occsvc-card-domain {\r\n  display: inline-block;\r\n  font-size: 12px;\r\n  font-weight: 600;\r\n  opacity: 0.55;\r\n  font-family: monospace;\r\n}\r\n\r\n.occsvc-card-cta {\r\n  width: 100%;\r\n  justify-content: center;\r\n  margin-top: 4px;\r\n}\r\n\r\n/* ==========================================================================\r\n   RESPONSIVE — tablets down to the smallest phones\r\n   ========================================================================== */\r\n\r\n/* Tablets — 2 columns */\r\n@media (max-width: 992px) {\r\n  .occsvc-grid { grid-template-columns: repeat(2, 1fr); }\r\n  .occsvc-intro-title { font-size: 34px !important; }\r\n}\r\n\r\n/* Small tablets / large phones — still 2 columns, tighter spacing */\r\n@media (max-width: 768px) {\r\n  .occsvc-intro { padding-top: 20px; padding-bottom: 40px; }\r\n  .occsvc-intro-title { font-size: 30px !important; }\r\n  .occsvc-intro-lead { font-size: 15.5px !important; }\r\n  .occsvc-grid { gap: 18px; padding: 0 20px; }\r\n  .occsvc-card { padding: 22px; }\r\n}\r\n\r\n/* Standard phones — portrait, single column */\r\n@media (max-width: 575px) {\r\n  .occsvc-intro { padding: 18px 18px 32px; }\r\n  .occsvc-intro-eyebrow { font-size: 12px; padding: 6px 13px; }\r\n  .occsvc-intro-title { font-size: 25px !important; }\r\n  .occsvc-intro-lead { font-size: 14px !important; }\r\n  .occsvc-intro-sub { font-size: 13px !important; }\r\n  .occsvc-grid { grid-template-columns: 1fr; gap: 16px; padding: 0 18px; }\r\n  .occsvc-status-row { flex-direction: column; align-items: stretch; padding: 0 18px; gap: 10px; }\r\n  .occsvc-recheck-btn { width: 100%; justify-content: center; }\r\n  .occsvc-card { padding: 20px; }\r\n  .occsvc-card-logo-wrap { width: 52px; height: 52px; }\r\n  .occsvc-card-title { font-size: 17px !important; }\r\n}\r\n\r\n/* Compact phones */\r\n@media (max-width: 400px) {\r\n  .occsvc-intro { padding: 14px 14px 26px; }\r\n  .occsvc-intro-title { font-size: 22px !important; }\r\n  .occsvc-grid { padding: 0 14px; }\r\n  .occsvc-card { padding: 18px; border-radius: 16px; }\r\n  .occsvc-card-top { flex-wrap: wrap; }\r\n}\r\n\r\n/* Smallest phones */\r\n@media (max-width: 374px) {\r\n  .occsvc-intro-title { font-size: 20px !important; }\r\n  .occsvc-card-logo-wrap { width: 46px; height: 46px; border-radius: 12px; }\r\n  .occsvc-card-tag { font-size: 10.5px; padding: 4px 8px; }\r\n}\r\n\r\n/* Phones — landscape */\r\n@media (max-width: 900px) and (orientation: landscape) {\r\n  .occsvc-intro { padding-top: 14px; padding-bottom: 24px; }\r\n  .occsvc-intro-title { font-size: 26px !important; }\r\n  .occsvc-intro-sub { display: none; }\r\n  .occsvc-grid { grid-template-columns: repeat(2, 1fr); }\r\n}", ""]);
